function LevelUpModal({ level, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 4000);
    return () => clearTimeout(t);
  }, [onClose]);

  return (
    <div
      onClick={onClose}
      style={{
        position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.92)',
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        zIndex: 3000,
      }}
    >
      <div style={{
        background: 'linear-gradient(135deg, #1a0d2e, #0d1a2e)',
        border: `2px solid ${C.gold}`,
        borderRadius: 24, padding: '48px 40px',
        textAlign: 'center',
        boxShadow: `0 0 80px ${C.gold}55`,
        animation: 'lvlUp 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)',
      }}>
        <div style={{ fontSize: 56, marginBottom: 16 }}>⭐</div>
        <div style={{ fontSize: 13, color: C.muted, letterSpacing: 3, marginBottom: 8 }}>
          LEVEL UP!
        </div>
        <div style={{ fontSize: 52, fontWeight: 700, color: C.gold, lineHeight: 1 }}>
          Lv.{level.lv}
        </div>
        <div style={{ fontSize: 22, fontWeight: 700, color: C.accent, marginTop: 12, marginBottom: 24 }}>
          {level.name}
        </div>
        <div style={{ fontSize: 12, color: C.muted }}>タップで閉じる</div>
      </div>
      <style>{`
        @keyframes lvlUp { from{opacity:0;transform:scale(0.5)} to{opacity:1;transform:scale(1)} }
      `}</style>
    </div>
  );
}

// ============================================================
// TimerModal
// ============================================================

function TimerModal({ item, onClose, onComplete }) {
  const [seconds,   setSeconds]   = useState(0);
  const [running,   setRunning]   = useState(false);
  const [countdown, setCountdown] = useState(false);
  const [flash,     setFlash]     = useState(false);
  const prevSecondsRef = useRef(-1);
  const intervalRef    = useRef(null);
  const target = item.minutes * 60;
  const over   = seconds > target;

  useEffect(() => {
    if (running) {
      intervalRef.current = setInterval(() => setSeconds(s => s + 1), 1000);
    } else {
      clearInterval(intervalRef.current);
    }
    return () => clearInterval(intervalRef.current);
  }, [running]);

  // Flash + vibrate when target is first reached
  useEffect(() => {
    if (seconds === target && prevSecondsRef.current === target - 1) {
      setFlash(true);
      navigator.vibrate?.([100, 50, 100]);
      const t = setTimeout(() => setFlash(false), 1000);
      prevSecondsRef.current = seconds;
      return () => clearTimeout(t);
    }
    prevSecondsRef.current = seconds;
  }, [seconds, target]);

  const display = countdown ? Math.max(target - seconds, 0) : seconds;

  function handleComplete() {
    clearInterval(intervalRef.current);
    navigator.vibrate?.([80, 40, 80]);
    onComplete(seconds);
  }

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000,
    }}>
      <div style={{
        background: C.card, borderRadius: 20, padding: '32px 28px',
        width: 320, textAlign: 'center', border: `1px solid ${C.border}`,
        boxShadow: `0 0 40px ${C.accent}22`,
      }}>
        <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 4 }}>
          {item.title || item.name}
        </div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 10 }}>目安: {item.minutes}分</div>

        <button
          onClick={() => setCountdown(c => !c)}
          style={{
            background: 'none', border: `1px solid ${C.muted}44`,
            borderRadius: 6, padding: '3px 12px', color: C.muted,
            cursor: 'pointer', fontSize: 11, marginBottom: 20,
          }}
        >
          {countdown ? '⏳ カウントダウン' : '⏱ カウントアップ'}
        </button>

        <div style={{
          fontSize: 60, fontWeight: 700, fontFamily: 'monospace',
          color: over ? C.orange : flash ? C.gold : C.accent,
          marginBottom: 8, letterSpacing: 2,
          transition: 'color 0.2s',
          animation: flash ? 'timerFlash 0.4s ease alternate 2' : 'none',
        }}>
          {formatTimer(display)}
        </div>

        {seconds === target && !over && (
          <div style={{ fontSize: 12, color: C.gold, marginBottom: 4 }}>✨ 目安時間に達しました！</div>
        )}
        {over && (
          <div style={{ fontSize: 12, color: C.orange, marginBottom: 4 }}>⚠ 目安時間を超えました</div>
        )}

        <div style={{ display: 'flex', gap: 10, justifyContent: 'center', marginTop: 20 }}>
          <button
            onClick={() => setRunning(r => !r)}
            style={{
              padding: '10px 18px', borderRadius: 10, border: 'none',
              background: running ? C.muted + '55' : C.accent,
              color: running ? C.text : '#000',
              fontWeight: 700, cursor: 'pointer', fontSize: 14,
            }}
          >
            {running ? '停止' : '開始'}
          </button>
          <button
            onClick={handleComplete}
            style={{
              padding: '10px 18px', borderRadius: 10, border: 'none',
              background: C.green, color: '#fff',
              fontWeight: 700, cursor: 'pointer', fontSize: 14,
            }}
          >
            完了
          </button>
          <button
            onClick={onClose}
            style={{
              padding: '10px 18px', borderRadius: 10, border: 'none',
              background: '#1f2937', color: C.muted,
              fontWeight: 700, cursor: 'pointer', fontSize: 14,
            }}
          >
            閉じる
          </button>
        </div>
      </div>
      <style>{`
        @keyframes timerFlash {
          from { opacity: 1; transform: scale(1.06); }
          to   { opacity: 0.5; transform: scale(0.96); }
        }
      `}</style>
    </div>
  );
}

// ============================================================
// RewardPopup
// ============================================================

function RewardPopup({ reward, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 3000);
    return () => clearTimeout(t);
  }, [onClose]);

  return (
    <div style={{
      position: 'fixed', top: 72, left: '50%', transform: 'translateX(-50%)',
      background: 'linear-gradient(135deg, #1a1040, #0d1a2e)',
      border: `2px solid ${C.gold}`,
      borderRadius: 18, padding: '20px 32px',
      textAlign: 'center', zIndex: 2000,
      boxShadow: `0 0 40px ${C.gold}44`,
      minWidth: 240,
      animation: 'fadeSlideIn 0.3s ease',
    }}>
      <div style={{ fontSize: 36, marginBottom: 8 }}>{reward.icon}</div>
      <div style={{ fontSize: 15, fontWeight: 700, color: C.gold }}>{reward.title}</div>
      <div style={{ fontSize: 26, fontWeight: 700, color: C.accent, margin: '8px 0' }}>
        +{reward.xp} XP
      </div>
      <div style={{ fontSize: 12, color: C.text }}>{reward.message}</div>
    </div>
  );
}

// ============================================================
// XPParticles
// ============================================================

function XPParticles({ xp, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 1400);
    return () => clearTimeout(t);
  }, [onDone]);

  return (
    <div style={{
      position: 'fixed', top: '45%', left: '50%',
      transform: 'translate(-50%,-50%)',
      pointerEvents: 'none', zIndex: 1500,
    }}>
      {[...Array(6)].map((_, i) => (
        <div key={i} style={{
          position: 'absolute',
          color: C.gold, fontWeight: 700, fontSize: 13,
          left: `${(i - 3) * 28}px`, top: 0,
          opacity: 0,
          animation: `floatUp${i % 3} 1.4s ease-out forwards`,
          animationDelay: `${i * 60}ms`,
        }}>
          +{xp}XP
        </div>
      ))}
      <style>{`
        @keyframes floatUp0 { 0%{opacity:1;transform:translateY(0)} 100%{opacity:0;transform:translateY(-60px)} }
        @keyframes floatUp1 { 0%{opacity:1;transform:translateY(0)} 100%{opacity:0;transform:translateY(-80px)} }
        @keyframes floatUp2 { 0%{opacity:1;transform:translateY(0)} 100%{opacity:0;transform:translateY(-50px)} }
        @keyframes fadeSlideIn { from{opacity:0;transform:translateX(-50%) translateY(-10px)} to{opacity:1;transform:translateX(-50%) translateY(0)} }
      `}</style>
    </div>
  );
}

// ============================================================
// WeeklyChart
// ============================================================

function WeeklyChart({ weeklyData, todayIndex }) {
  const days = ['日', '月', '火', '水', '木', '金', '土'];
  const max  = Math.max(...weeklyData, 1);

  return (
    <div style={{ background: C.card, borderRadius: 12, padding: 16, marginBottom: 16 }}>
      <div style={{ fontSize: 12, color: C.muted, marginBottom: 12 }}>週間達成数</div>
      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 6, height: 80 }}>
        {weeklyData.map((val, i) => (
          <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3 }}>
            <div style={{ fontSize: 10, color: C.muted, minHeight: 14 }}>{val > 0 ? val : ''}</div>
            <div style={{
              width: '100%',
              height: `${Math.max((val / max) * 56, 4)}px`,
              background: i === todayIndex
                ? `linear-gradient(180deg, ${C.accent}, ${C.purple})`
                : C.muted + '44',
              borderRadius: 4,
              transition: 'height 0.4s ease',
            }} />
            <div style={{
              fontSize: 11,
              color: i === todayIndex ? C.accent : C.muted,
              fontWeight: i === todayIndex ? 700 : 400,
            }}>{days[i]}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ============================================================
// QuestTab
// ============================================================

function QuestTab({ data, onCompleteQuest, onNavigate }) {
  const [timerItem, setTimerItem] = useState(null);

  const level      = getLevel(data.xp);
  const nextLevel  = getNextLevel(data.xp);
  const progress   = getXpProgress(data.xp);
  const todayIndex = getDayIndex();
  const todayDone  = data.completedToday.length;
  const thisWeek   = data.weeklyData.reduce((a, b) => a + b, 0);

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* Level card */}
      <div style={{
        background: 'linear-gradient(135deg, #0d1a2e, #1a0d2e)',
        border: `1px solid ${C.accent}33`,
        borderRadius: 16, padding: '20px 20px 16px', marginBottom: 16,
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 14 }}>
          <div>
            <div style={{ fontSize: 11, color: C.muted, marginBottom: 2 }}>Lv.{level.lv}</div>
            <div style={{ fontSize: 20, fontWeight: 700, color: C.accent }}>{level.name}</div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontSize: 26, fontWeight: 700, color: C.gold }}>{data.xp}</div>
            <div style={{ fontSize: 11, color: C.muted }}>XP</div>
          </div>
        </div>
        <div style={{ height: 8, background: C.border, borderRadius: 4, overflow: 'hidden' }}>
          <div style={{
            height: '100%', width: `${progress * 100}%`,
            background: `linear-gradient(90deg, ${C.purple}, ${C.accent})`,
            borderRadius: 4, transition: 'width 0.6s ease',
          }} />
        </div>
        {nextLevel ? (
          <div style={{ fontSize: 11, color: C.muted, marginTop: 6, textAlign: 'right' }}>
            あと {nextLevel.xp - data.xp} XP → {nextLevel.name}
          </div>
        ) : (
          <div style={{ fontSize: 11, color: C.gold, marginTop: 6, textAlign: 'right' }}>最高レベル達成！</div>
        )}
      </div>

      {/* Streak badge */}
      {data.streak > 0 && (
        <div style={{
          display: 'inline-flex', alignItems: 'center', gap: 6,
          background: '#1f1508', border: `1px solid ${C.orange}55`,
          borderRadius: 20, padding: '6px 14px', marginBottom: 16,
          fontSize: 14, color: C.orange, fontWeight: 700,
        }}>
          🔥 {data.streak}日連続
        </div>
      )}

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 8, marginBottom: 16 }}>
        {[
          { label: '今日完了', value: todayDone,       color: C.accent },
          { label: '累計',    value: data.totalTasks,  color: C.purple },
          { label: '今週',    value: thisWeek,         color: C.gold   },
        ].map(s => (
          <div key={s.label} style={{
            background: C.card, borderRadius: 12, padding: '12px 8px', textAlign: 'center',
          }}>
            <div style={{ fontSize: 24, fontWeight: 700, color: s.color }}>{s.value}</div>
            <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>{s.label}</div>
          </div>
        ))}
      </div>

      {/* Weekly chart */}
      <WeeklyChart weeklyData={data.weeklyData} todayIndex={todayIndex} />

      {/* Quick actions */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 16 }}>
        <button onClick={() => onNavigate('procedure')} style={{
          background: `${C.purple}22`, border: `1px solid ${C.purple}`,
          borderRadius: 12, padding: '12px 14px',
          color: C.text, cursor: 'pointer', textAlign: 'left',
          fontSize: 14, fontWeight: 600,
        }}>
          📋 手順ガイドを開く
        </button>
        <button onClick={() => onNavigate('reflection')} style={{
          background: `${C.green}22`, border: `1px solid ${C.green}`,
          borderRadius: 12, padding: '12px 14px',
          color: C.text, cursor: 'pointer', textAlign: 'left',
          fontSize: 14, fontWeight: 600,
        }}>
          📝 振り返りを書く
        </button>
      </div>

      {/* Quest list */}
      <div style={{ fontSize: 13, color: C.muted, marginBottom: 8 }}>デイリークエスト</div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        {QUESTS.map(quest => {
          const done = data.completedToday.includes(quest.id);
          return (
            <div
              key={quest.id}
              onClick={() => !done && setTimerItem(quest)}
              style={{
                background: done ? '#0d1a10' : C.card,
                border: `1px solid ${done ? C.green + '44' : C.border}`,
                borderRadius: 12, padding: '14px 16px',
                display: 'flex', alignItems: 'center', gap: 12,
                cursor: done ? 'default' : 'pointer',
                opacity: done ? 0.65 : 1,
              }}
            >
              <div style={{ fontSize: 22 }}>{quest.icon}</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{quest.name}</div>
                <div style={{ fontSize: 11, color: C.muted }}>▶ {quest.minutes}分 · +{quest.xp} XP</div>
              </div>
              {done ? (
                <div style={{ fontSize: 20, color: C.green }}>✓</div>
              ) : (
                <div style={{
                  background: `${C.accent}22`, border: `1px solid ${C.accent}`,
                  borderRadius: 8, padding: '3px 9px',
                  fontSize: 12, color: C.accent, fontWeight: 700,
                }}>
                  +{quest.xp}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {timerItem && (
        <TimerModal
          item={timerItem}
          onClose={() => setTimerItem(null)}
          onComplete={(elapsed) => { onCompleteQuest(timerItem, elapsed); setTimerItem(null); }}
        />
      )}
    </div>
  );
}

// ============================================================
// ProcedureTab
// ============================================================

function ProcedureTab({ data, onCompleteCase, onNavigate, onUpdateProcedure }) {
  const [timerItem, setTimerItem] = useState(null);

  const selectedCase = data.procedureCase || null;
  const checkedSteps = data.procedureChecked || [];
  const allDone      = checkedSteps.length === STEPS.length;

  function setSelectedCase(c) {
    onUpdateProcedure({ procedureCase: c, procedureChecked: [] });
  }

  function goBack() {
    onUpdateProcedure({ procedureCase: null, procedureChecked: [] });
  }

  function toggleStep(id) {
    const next = checkedSteps.includes(id)
      ? checkedSteps.filter(x => x !== id)
      : [...checkedSteps, id];
    onUpdateProcedure({ procedureChecked: next });
  }

  function handleComplete() {
    onCompleteCase(selectedCase);
    onUpdateProcedure({ procedureCase: null, procedureChecked: [] });
    onNavigate('reflection');
  }

  if (!selectedCase) {
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 6 }}>事例を選択</div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>
          どの事例の手順ガイドを使いますか？
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {CASES.map(c => (
            <button
              key={c.id}
              onClick={() => setSelectedCase(c)}
              style={{
                background: C.card, border: `1px solid ${C.accent}44`,
                borderRadius: 14, padding: '18px 20px',
                color: C.text, cursor: 'pointer', textAlign: 'left',
                fontSize: 16, fontWeight: 600,
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
              }}
            >
              {c.full}
              <span style={{ color: C.accent, fontSize: 20 }}>›</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* Back header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
        <button
          onClick={goBack}
          style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0 }}
        >
          ←
        </button>
        <div>
          <div style={{ fontSize: 16, fontWeight: 700, color: C.text }}>{selectedCase.full}</div>
          <div style={{ fontSize: 12, color: C.muted }}>{checkedSteps.length}/{STEPS.length} 完了</div>
        </div>
      </div>

      {/* Progress bar */}
      <div style={{ height: 4, background: C.border, borderRadius: 2, marginBottom: 20 }}>
        <div style={{
          height: '100%', width: `${(checkedSteps.length / STEPS.length) * 100}%`,
          background: C.green, borderRadius: 2, transition: 'width 0.3s',
        }} />
      </div>

      {/* Steps */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
        {STEPS.map(step => {
          const done = checkedSteps.includes(step.id);
          const pc   = PHASE_COLORS[step.phase] || C.muted;
          return (
            <div key={step.id} style={{
              background: done ? '#0d1a10' : C.card,
              border: `1px solid ${done ? C.green + '44' : C.border}`,
              borderRadius: 12, padding: '14px 16px',
            }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                <div
                  onClick={() => toggleStep(step.id)}
                  style={{
                    width: 34, height: 34, borderRadius: '50%',
                    background: done ? C.green : pc + '22',
                    border: `2px solid ${done ? C.green : pc}`,
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    cursor: 'pointer', flexShrink: 0,
                    fontSize: done ? 14 : 13, fontWeight: 700,
                    color: done ? '#fff' : pc,
                  }}
                >
                  {done ? '✓' : step.id}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ marginBottom: 3 }}>
                    <span style={{
                      fontSize: 10, fontWeight: 700, color: pc,
                      background: pc + '22', borderRadius: 4, padding: '1px 6px',
                    }}>{step.phase}</span>
                  </div>
                  <div style={{ fontSize: 15, fontWeight: 600, color: C.text }}>{step.title}</div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>{step.hint}</div>
                </div>
                <button
                  onClick={() => setTimerItem(step)}
                  style={{
                    background: pc + '22', border: `1px solid ${pc}`,
                    borderRadius: 8, padding: '6px 10px',
                    color: pc, cursor: 'pointer',
                    fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap', flexShrink: 0,
                  }}
                >
                  ▶ {step.minutes}分
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {allDone && (
        <button
          onClick={handleComplete}
          style={{
            width: '100%', marginTop: 20, padding: 16,
            background: `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
            border: 'none', borderRadius: 14,
            color: '#fff', fontWeight: 700, fontSize: 16, cursor: 'pointer',
          }}
        >
          🎉 事例クリア！ +100 XP
        </button>
      )}

      {timerItem && (
        <TimerModal
          item={timerItem}
          onClose={() => setTimerItem(null)}
          onComplete={() => { toggleStep(timerItem.id); setTimerItem(null); }}
        />
      )}
    </div>
  );
}

// ============================================================
// ReflectionTab
// ============================================================

function ReflectionTab({ data, onSaveNote }) {
  const [selectedCase,  setSelectedCase]  = useState(null);
  const [date,          setDate]          = useState(todayStr());
  const [good,          setGood]          = useState('');
  const [improve,       setImprove]       = useState('');
  const [keywords,      setKeywords]      = useState('');
  const [nextAction,    setNextAction]    = useState('');
  const [saved,         setSaved]         = useState(false);
  const [selectedNote,  setSelectedNote]  = useState(null);

  function handleSave() {
    if (!selectedCase) return;
    onSaveNote({
      id: Date.now(),
      caseName: selectedCase.full,
      date, good, improve, keywords, nextAction,
      time: formatDateTime(),
    });
    setGood(''); setImprove(''); setKeywords(''); setNextAction('');
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  }

  function handleDelete(id) {
    onSaveNote(null, id);
    setSelectedNote(null);
  }

  if (selectedNote) {
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 20 }}>
          <button
            onClick={() => setSelectedNote(null)}
            style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0 }}
          >←</button>
          <div>
            <div style={{ fontSize: 16, fontWeight: 700, color: C.text }}>{selectedNote.caseName}</div>
            <div style={{ fontSize: 12, color: C.muted }}>{selectedNote.date} · {selectedNote.time}</div>
          </div>
        </div>
        {[
          { label: 'よかった点',    value: selectedNote.good,       color: C.green  },
          { label: '改善点',        value: selectedNote.improve,    color: C.orange },
          { label: '重要キーワード', value: selectedNote.keywords,   color: C.accent },
          { label: '次回やること',  value: selectedNote.nextAction, color: C.purple },
        ].filter(f => f.value).map(f => (
          <div key={f.label} style={{
            background: f.color + '11', border: `1px solid ${f.color}33`,
            borderRadius: 12, padding: 16, marginBottom: 12,
          }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: f.color, marginBottom: 6 }}>{f.label}</div>
            <div style={{ fontSize: 14, color: C.text, whiteSpace: 'pre-wrap', lineHeight: 1.6 }}>{f.value}</div>
          </div>
        ))}
        <button
          onClick={() => handleDelete(selectedNote.id)}
          style={{
            width: '100%', marginTop: 12, padding: 14,
            background: C.red + '22', border: `1px solid ${C.red}`,
            borderRadius: 12, color: C.red, cursor: 'pointer',
            fontWeight: 700, fontSize: 14,
          }}
        >
          削除
        </button>
      </div>
    );
  }

  const ta = {
    width: '100%', padding: 12, background: '#1f2937',
    border: '1px solid #374151', borderRadius: 8,
    color: C.text, fontSize: 14, resize: 'vertical',
    minHeight: 80, fontFamily: 'inherit', boxSizing: 'border-box',
    outline: 'none',
  };

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      <div style={{ fontSize: 13, color: C.muted, marginBottom: 8 }}>事例を選択</div>
      <div style={{ display: 'flex', gap: 6, marginBottom: 16 }}>
        {CASES.map(c => (
          <button
            key={c.id}
            onClick={() => setSelectedCase(c)}
            style={{
              flex: 1, padding: '8px 4px', borderRadius: 8, border: 'none',
              background: selectedCase?.id === c.id ? C.accent : C.card,
              color: selectedCase?.id === c.id ? '#000' : C.muted,
              fontWeight: selectedCase?.id === c.id ? 700 : 400,
              cursor: 'pointer', fontSize: 12,
            }}
          >
            {c.name}
          </button>
        ))}
      </div>

      <div style={{ marginBottom: 14 }}>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 6 }}>解いた日付</div>
        <input
          type="date" value={date} onChange={e => setDate(e.target.value)}
          style={{
            background: '#1f2937', border: '1px solid #374151',
            borderRadius: 8, padding: '8px 12px', color: C.text,
            fontSize: 14, width: '100%', boxSizing: 'border-box', outline: 'none',
          }}
        />
      </div>

      {[
        { label: '✅ よかった点',    value: good,       setter: setGood,       color: C.green  },
        { label: '🔧 改善点',        value: improve,    setter: setImprove,    color: C.orange },
        { label: '🔑 重要キーワード', value: keywords,   setter: setKeywords,   color: C.accent },
        { label: '🎯 次回やること',  value: nextAction, setter: setNextAction, color: C.purple },
      ].map(f => (
        <div key={f.label} style={{ marginBottom: 14 }}>
          <div style={{ fontSize: 13, color: f.color, fontWeight: 600, marginBottom: 6 }}>{f.label}</div>
          <textarea
            value={f.value}
            onChange={e => f.setter(e.target.value)}
            style={ta}
            placeholder={`${f.label}を入力...`}
          />
        </div>
      ))}

      <button
        onClick={handleSave}
        disabled={!selectedCase}
        style={{
          width: '100%', padding: 14,
          background: selectedCase
            ? `linear-gradient(135deg, ${C.purple}, ${C.accent})`
            : C.muted + '44',
          border: 'none', borderRadius: 12,
          color: selectedCase ? '#fff' : C.muted,
          fontWeight: 700, fontSize: 15,
          cursor: selectedCase ? 'pointer' : 'not-allowed',
        }}
      >
        {saved ? '✓ 保存しました' : '保存'}
      </button>

      {data.notes.length > 0 && (
        <>
          <div style={{ fontSize: 13, color: C.muted, margin: '20px 0 8px' }}>
            保存済みノート ({data.notes.length})
          </div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {[...data.notes].reverse().map(note => (
              <div
                key={note.id}
                onClick={() => setSelectedNote(note)}
                style={{
                  background: C.card, border: `1px solid ${C.border}`,
                  borderRadius: 12, padding: '12px 16px',
                  cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                }}
              >
                <div>
                  <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{note.caseName}</div>
                  <div style={{ fontSize: 12, color: C.muted }}>{note.date}</div>
                </div>
                <span style={{ color: C.accent, fontSize: 18 }}>›</span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ============================================================
// HistoryTab
// ============================================================

function HistoryTab({ data }) {
  const [histView, setHistView]   = useState('calendar');
  const [calMode, setCalMode]     = useState('month');
  const [calMonth, setCalMonth]   = useState(new Date());
  const [selectedDay, setSelectedDay] = useState(null);

  const history         = data.history || [];
  const recent          = [...history].slice(-40).reverse();
  const totalSeconds    = history.reduce((sum, item) => sum + (item.elapsed || 0), 0);
  const caseClears      = history.filter(item => (item.name || '').includes('クリア')).length;
  const weeklyXpHistory = data.weeklyXpHistory || [];
  const currentWeekXp   = (data.weeklyXpData || []).reduce((a, b) => a + b, 0);
  const chartWeeks      = [...weeklyXpHistory.slice(-4), currentWeekXp];
  const maxWkXp         = Math.max(...chartWeeks, 1);
  const showChart       = chartWeeks.some(v => v > 0);
  const dailyLog        = data.dailyLog || {};
  const todayKey        = todayStr();

  function getDayColor(dateKey) {
    const e = dailyLog[dateKey];
    if (!e || e.tasks === 0) return '#1e293b';
    if (e.tasks <= 2) return C.purple + '66';
    if (e.tasks <= 5) return C.purple;
    if (e.tasks <= 9) return C.accent + 'aa';
    return C.gold;
  }

  // Monthly calendar grid
  const year  = calMonth.getFullYear();
  const month = calMonth.getMonth();
  const firstDay    = new Date(year, month, 1).getDay();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const calDays = [];
  for (let i = 0; i < firstDay; i++) calDays.push(null);
  for (let d = 1; d <= daysInMonth; d++) {
    const dk = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    calDays.push({ dateKey: dk, day: d });
  }

  // Year heatmap: 53 weeks ending at today
  function getYearGrid() {
    const today = new Date();
    const start = new Date(today);
    start.setDate(today.getDate() - today.getDay() - 52 * 7);
    const weeks = [];
    let cur = new Date(start);
    while (cur <= today || weeks.length < 53) {
      const week = [];
      for (let d = 0; d < 7; d++) {
        week.push(cur <= today ? new Date(cur) : null);
        cur.setDate(cur.getDate() + 1);
      }
      weeks.push(week);
      if (cur > today && week.every(x => x === null || localDateStr(x) >= todayKey)) break;
    }
    return weeks;
  }

  function getMonthLabels(weeks) {
    const labels = []; let lastM = -1;
    weeks.forEach((week, wi) => {
      const first = week.find(Boolean);
      if (first) { const m = first.getMonth(); if (m !== lastM) { labels.push({ wi, label: `${m + 1}月` }); lastM = m; } }
    });
    return labels;
  }

  const yearWeeks = calMode === 'year' ? getYearGrid() : [];

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* View toggle */}
      <div style={{ display: 'flex', gap: 6, marginBottom: 16 }}>
        {[{ id: 'calendar', label: '📅 カレンダー' }, { id: 'stats', label: '📊 統計' }, { id: 'list', label: '📋 履歴' }].map(v => (
          <button key={v.id} onClick={() => setHistView(v.id)} style={{
            flex: 1, padding: '8px 0', borderRadius: 20, border: 'none',
            background: histView === v.id ? C.accent : C.card,
            color: histView === v.id ? '#000' : C.muted,
            fontWeight: histView === v.id ? 700 : 400,
            cursor: 'pointer', fontSize: 12,
          }}>{v.label}</button>
        ))}
      </div>

      {/* ---- CALENDAR VIEW ---- */}
      {histView === 'calendar' && (
        <div>
          <div style={{ display: 'flex', gap: 6, marginBottom: 14, justifyContent: 'center' }}>
            {[{ id: 'month', label: '月' }, { id: 'year', label: '年' }].map(m => (
              <button key={m.id} onClick={() => { setCalMode(m.id); setSelectedDay(null); }} style={{
                padding: '5px 24px', borderRadius: 20, border: 'none',
                background: calMode === m.id ? C.purple : C.card,
                color: calMode === m.id ? '#fff' : C.muted,
                fontWeight: calMode === m.id ? 700 : 400,
                cursor: 'pointer', fontSize: 13,
              }}>{m.label}</button>
            ))}
          </div>

          {/* Monthly calendar */}
          {calMode === 'month' && (
            <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 12 }}>
                <button onClick={() => { const d = new Date(calMonth); d.setMonth(d.getMonth() - 1); setCalMonth(d); setSelectedDay(null); }}
                  style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 20, padding: '0 8px' }}>◀</button>
                <div style={{ fontSize: 16, fontWeight: 700, color: C.text }}>{year}年{month + 1}月</div>
                <button onClick={() => { const d = new Date(calMonth); d.setMonth(d.getMonth() + 1); setCalMonth(d); setSelectedDay(null); }}
                  style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 20, padding: '0 8px' }}>▶</button>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2, marginBottom: 4 }}>
                {['日','月','火','水','木','金','土'].map((d, i) => (
                  <div key={d} style={{ textAlign: 'center', fontSize: 10, padding: '2px 0',
                    color: i === 0 ? '#ef4444' : i === 6 ? '#60a5fa' : C.muted }}>{d}</div>
                ))}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: 2 }}>
                {calDays.map((cell, i) => {
                  if (!cell) return <div key={i} />;
                  const { dateKey, day } = cell;
                  const isToday    = dateKey === todayKey;
                  const isSelected = selectedDay === dateKey;
                  const e = dailyLog[dateKey];
                  return (
                    <div key={i} onClick={() => setSelectedDay(isSelected ? null : dateKey)} style={{
                      aspectRatio: '1', borderRadius: 8,
                      background: getDayColor(dateKey),
                      border: `1.5px solid ${isSelected ? C.gold : isToday ? C.accent : 'transparent'}`,
                      display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                      cursor: 'pointer',
                    }}>
                      <div style={{ fontSize: 11, color: isToday ? C.accent : C.text, fontWeight: isToday ? 700 : 400 }}>{day}</div>
                      {e && e.tasks > 0 && <div style={{ fontSize: 8, color: '#fff', opacity: 0.85 }}>{e.tasks}</div>}
                    </div>
                  );
                })}
              </div>

              {selectedDay && (() => {
                const e = dailyLog[selectedDay];
                const [, m, d] = selectedDay.split('-');
                return (
                  <div style={{ marginTop: 12, padding: '10px 14px', background: C.purple + '22', border: `1px solid ${C.purple}55`, borderRadius: 10 }}>
                    {e && e.tasks > 0 ? (
                      <>
                        <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 6 }}>{parseInt(m)}月{parseInt(d)}日</div>
                        <div style={{ display: 'flex', gap: 16 }}>
                          <div style={{ fontSize: 13, color: C.accent }}>✓ {e.tasks} タスク</div>
                          <div style={{ fontSize: 13, color: C.gold }}>＋{e.xp} XP</div>
                        </div>
                      </>
                    ) : (
                      <div style={{ fontSize: 13, color: C.muted }}>{parseInt(m)}月{parseInt(d)}日 — 活動なし</div>
                    )}
                  </div>
                );
              })()}
            </div>
          )}

          {/* Year heatmap */}
          {calMode === 'year' && (
            <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
              <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 12 }}>過去1年の学習記録</div>
              <div style={{ overflowX: 'auto', paddingBottom: 4 }}>
                {(() => {
                  const CELL = 11; const GAP = 2;
                  const monthLabels = getMonthLabels(yearWeeks);
                  return (
                    <div style={{ display: 'inline-flex', gap: 0 }}>
                      {/* Day labels */}
                      <div style={{ display: 'flex', flexDirection: 'column', gap: GAP, marginTop: 16, marginRight: 4 }}>
                        {['日','月','火','水','木','金','土'].map((l, i) => (
                          <div key={i} style={{ height: CELL, fontSize: 8, color: C.muted, lineHeight: `${CELL}px` }}>
                            {i % 2 === 1 ? l : ''}
                          </div>
                        ))}
                      </div>
                      {/* Weeks */}
                      <div>
                        <div style={{ display: 'flex', gap: GAP, marginBottom: 2, height: 14 }}>
                          {yearWeeks.map((_, wi) => {
                            const ml = monthLabels.find(m => m.wi === wi);
                            return (
                              <div key={wi} style={{ width: CELL, fontSize: 8, color: C.muted, overflow: 'visible', whiteSpace: 'nowrap' }}>
                                {ml ? ml.label : ''}
                              </div>
                            );
                          })}
                        </div>
                        <div style={{ display: 'flex', gap: GAP }}>
                          {yearWeeks.map((week, wi) => (
                            <div key={wi} style={{ display: 'flex', flexDirection: 'column', gap: GAP }}>
                              {week.map((date, di) => {
                                if (!date) return <div key={di} style={{ width: CELL, height: CELL }} />;
                                const dk = localDateStr(date);
                                const isToday = dk === todayKey;
                                return (
                                  <div key={di} onClick={() => setSelectedDay(selectedDay === dk ? null : dk)} style={{
                                    width: CELL, height: CELL, borderRadius: 2,
                                    background: getDayColor(dk),
                                    border: isToday ? `1px solid ${C.accent}` : selectedDay === dk ? `1px solid ${C.gold}` : 'none',
                                    cursor: 'pointer',
                                  }} />
                                );
                              })}
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  );
                })()}
              </div>

              {/* Legend */}
              <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginTop: 10 }}>
                <div style={{ fontSize: 10, color: C.muted }}>少</div>
                {['#1e293b', C.purple + '66', C.purple, C.accent + 'aa', C.gold].map((c, i) => (
                  <div key={i} style={{ width: 11, height: 11, borderRadius: 2, background: c }} />
                ))}
                <div style={{ fontSize: 10, color: C.muted }}>多</div>
              </div>

              {selectedDay && dailyLog[selectedDay] && (() => {
                const e = dailyLog[selectedDay];
                const [, m, d] = selectedDay.split('-');
                return (
                  <div style={{ marginTop: 10, padding: '8px 12px', background: C.purple + '22', border: `1px solid ${C.purple}55`, borderRadius: 10 }}>
                    <div style={{ display: 'flex', gap: 16, alignItems: 'center' }}>
                      <div style={{ fontSize: 12, color: C.muted }}>{parseInt(m)}月{parseInt(d)}日</div>
                      <div style={{ fontSize: 12, color: C.accent }}>✓ {e.tasks} タスク</div>
                      <div style={{ fontSize: 12, color: C.gold }}>＋{e.xp} XP</div>
                    </div>
                  </div>
                );
              })()}
            </div>
          )}
        </div>
      )}

      {/* ---- STATS VIEW ---- */}
      {histView === 'stats' && (
        <div style={{ background: C.card, border: `1px solid ${C.border}`, borderRadius: 14, padding: 16 }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: C.text, marginBottom: 14 }}>📊 学習統計</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: showChart ? 16 : 0 }}>
            <div style={{ background: C.accent + '11', border: `1px solid ${C.accent}33`, borderRadius: 10, padding: '10px 12px' }}>
              <div style={{ fontSize: 10, color: C.muted, marginBottom: 4 }}>⏱ 総学習時間</div>
              <div style={{ fontSize: 18, fontWeight: 700, color: C.accent }}>{totalSeconds > 0 ? formatStudyTime(totalSeconds) : '—'}</div>
            </div>
            <div style={{ background: C.gold + '11', border: `1px solid ${C.gold}33`, borderRadius: 10, padding: '10px 12px' }}>
              <div style={{ fontSize: 10, color: C.muted, marginBottom: 4 }}>🎯 事例クリア</div>
              <div style={{ fontSize: 18, fontWeight: 700, color: C.gold }}>{caseClears}回</div>
            </div>
          </div>
          {showChart && (
            <>
              <div style={{ fontSize: 11, color: C.muted, marginBottom: 8 }}>週別XP推移</div>
              <div style={{ display: 'flex', alignItems: 'flex-end', gap: 6, height: 64 }}>
                {chartWeeks.map((xp, i) => {
                  const isCurrent = i === chartWeeks.length - 1;
                  const label = isCurrent ? '今週' : `${chartWeeks.length - 1 - i}週前`;
                  return (
                    <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                      <div style={{ fontSize: 9, color: C.muted, minHeight: 12 }}>{xp > 0 ? xp : ''}</div>
                      <div style={{
                        width: '100%', height: `${Math.max((xp / maxWkXp) * 40, 3)}px`,
                        background: isCurrent ? `linear-gradient(180deg, ${C.accent}, ${C.purple})` : C.muted + '55',
                        borderRadius: 3,
                      }} />
                      <div style={{ fontSize: 9, color: isCurrent ? C.accent : C.muted, fontWeight: isCurrent ? 700 : 400 }}>{label}</div>
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>
      )}

      {/* ---- LIST VIEW ---- */}
      {histView === 'list' && (
        recent.length === 0 ? (
          <div style={{ padding: '60px 0', textAlign: 'center', color: C.muted }}>
            <div style={{ fontSize: 48, marginBottom: 12 }}>📜</div>
            <div style={{ fontSize: 16 }}>まだ履歴がありません</div>
            <div style={{ fontSize: 13, marginTop: 8 }}>クエストを完了すると表示されます</div>
          </div>
        ) : (
          <>
            <div style={{ fontSize: 13, color: C.muted, marginBottom: 12 }}>完了タスク（最新{recent.length}件）</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {recent.map((item, i) => (
                <div key={i} style={{
                  background: C.card, border: `1px solid ${C.border}`,
                  borderRadius: 12, padding: '12px 16px',
                  display: 'flex', alignItems: 'center', gap: 12,
                }}>
                  <div style={{ fontSize: 22 }}>{item.icon || '✅'}</div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{item.name}</div>
                    <div style={{ fontSize: 12, color: C.muted }}>{item.time}{item.elapsed ? ` · ${formatStudyTime(item.elapsed)}` : ''}</div>
                  </div>
                  <div style={{ fontSize: 13, fontWeight: 700, color: C.gold, background: C.gold + '22', borderRadius: 8, padding: '3px 8px' }}>
                    +{item.xp}
                  </div>
                </div>
              ))}
            </div>
          </>
        )
      )}
    </div>
  );
}

// ============================================================
// FinanceTab
// ============================================================

// ============================================================
// 間接法CFドリル（思考フロー式・数値ランダム）
// ============================================================

const CF_SEC = { op: C.accent, inv: C.purple, fin: C.orange };

function cfRnd(min, max, step) {
  return min + Math.floor(Math.random() * ((max - min) / step + 1)) * step;
}

function cfSigned(n) {
  return (n < 0 ? '−' : '＋') + Math.abs(n).toLocaleString();
}

function cfShuffle(opts) {
  const a = opts.map(o => ({ ...o }));
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function buildCfCase() {
  const c = {
    pretax:  cfRnd(700, 1600, 50),
    dep:     cfRnd(100, 300, 10),
    allow:   cfRnd(10, 60, 5),
    gain:    cfRnd(30, 90, 10),
    intExp:  cfRnd(20, 60, 5),
    intInc:  cfRnd(5, 25, 5),
    ar:      cfRnd(80, 200, 10),
    inv:     cfRnd(30, 90, 10),
    ap:      cfRnd(20, 80, 10),
    tax:     cfRnd(120, 260, 10),
    buyFix:  cfRnd(300, 600, 50),
    bookVal: cfRnd(80, 200, 10),
    buySec:  cfRnd(50, 200, 50),
    lendBk:  cfRnd(30, 100, 10),
    borrow:  cfRnd(200, 500, 50),
    repay:   cfRnd(100, 400, 50),
    issue:   cfRnd(50, 200, 50),
    divPaid: cfRnd(30, 150, 10),
    opening: cfRnd(300, 800, 50),
  };
  c.intPaid  = c.intExp - 5;
  c.intRecv  = c.intInc;
  c.sellFix  = c.bookVal + c.gain;
  return c;
}

function buildCfSteps(c, mode) {
  const s = [];
  const push = (o) => s.push({ sec: 'op', ...o, qs: (o.qs || []).map(q => ({ ...q, opts: cfShuffle(q.opts) })) });

  push({ name: '営業活動によるキャッシュ・フロー', kind: 'sec', auto: true, amt: 0, sign: 1 });

  push({ name: '税引前当期純利益', amt: c.pretax, sign: 1, kind: 'head', qs: [
    { step: '出発点', q: '間接法はどの利益から出発するか。',
      opts: [
        { t: '税引前当期純利益', ok: true },
        { t: '当期純利益（税引後）' },
        { t: '営業利益' },
        { t: '売上高' }],
      why: '法人税は小計の下で「実際に支払った額」として別に引く。だから上は税引前から始める。' }] });

  push({ name: '減価償却費', amt: c.dep, sign: 1, qs: [
    { step: '1／2　現金は動いたか', q: '減価償却費を計上したとき、当期の現金は出ていったか。',
      opts: [
        { t: '出ていっていない（過去の支出を配分しただけ）', ok: true },
        { t: '当期に出ていった' },
        { t: '半分だけ出ていった' }],
      why: '支出はモノを買った期に済んでいる。当期は帳簿上の費用だけが立っている。' },
    { step: '2／2　符号', q: 'では税引前利益にどう調整するか。',
      opts: [
        { t: '足し戻す（＋）', ok: true },
        { t: '差し引く（−）' }],
      why: '利益の計算で引かれているだけで現金は減っていないので、そのまま足して戻す。' }] });

  push({ name: '貸倒引当金の増加額', amt: c.allow, sign: 1, qs: [
    { step: '1／2　現金は動いたか', q: '引当金の繰入で現金は動いたか。',
      opts: [
        { t: '動いていない（将来の損失の見積り）', ok: true },
        { t: '動いた' }],
      why: '減価償却と同じ非資金費用の仲間。退職給付引当金や賞与引当金も同じ扱い。' },
    { step: '2／2　符号', q: '引当金が「増加」したときの符号は。',
      opts: [
        { t: '足し戻す（＋）', ok: true },
        { t: '差し引く（−）' }],
      why: '増加＝その分費用が立った＝現金は出ていない。減少なら逆に−。' }] });

  push({ name: '固定資産売却益', amt: c.gain, sign: -1, qs: [
    { step: '1／2　どの活動か', q: 'この利益はどの活動から生まれたものか。',
      opts: [
        { t: '投資活動（資産を売った）', ok: true },
        { t: '営業活動（本業のもうけ）' },
        { t: '財務活動（資金の回収）' }],
      why: '売却代金は全額が投資CFに入る。営業CFに利益を残すと二重計上になる。' },
    { step: '2／2　符号', q: '営業CFの中ではどう扱うか。',
      opts: [
        { t: '差し引く（−）／利益に含まれている分を取り消す', ok: true },
        { t: '足す（＋）／もうけだから' },
        { t: '調整しない／投資CFだけで処理する' }],
      why: '税引前利益にプラスで入っているので引いて消す。売却損なら逆に＋。' }] });

  push({ name: '支払利息', amt: c.intExp, sign: 1, qs: [
    { step: '1／3　現状', q: '支払利息は、税引前当期純利益の計算ですでにどうなっているか。',
      opts: [
        { t: '営業外費用として引かれている', ok: true },
        { t: 'まだ何も反映されていない' },
        { t: '営業外収益として加算されている' }],
      why: '出発点は、支払利息を引いたあとの数字。ここを押さえないと符号が決められない。' },
    { step: '2／3　置き場所', q: '利息の金額は、営業CFのどこで確定させるルールか。',
      opts: [
        { t: '小計より下で、実際に支払った額として計上する', ok: true },
        { t: '小計より上に、PLの発生額のまま置いておく' },
        { t: '営業CFには載せず、財務CFだけに載せる' }],
      why: '利息と法人税は発生額ではなく実際の収支額で、小計の下に並べる。これがすべての起点。' },
    { step: '3／3　符号', q: 'だから小計より上ではどうするか。',
      opts: [
        { t: 'いったん足し戻す（＋）', ok: true },
        { t: 'もう一度引く（−）' },
        { t: '何もしない' }],
      why: '「上でキャンセル → 下で実額」の二段構え。受取利息はこの逆になる。' }] });

  push({ name: '受取利息・受取配当金', amt: c.intInc, sign: -1, qs: [
    { step: '符号', q: '支払利息の逆に考える。小計より上ではどうするか。',
      opts: [
        { t: '差し引く（−）／下で実際の受取額を出すから', ok: true },
        { t: '足す（＋）／収入だから' },
        { t: '調整しない' }],
      why: '税引前利益にプラスで入っている分を消す。下で受取額を＋で計上する。' }] });

  push({ name: '売上債権の増加額', amt: c.ar, sign: -1, qs: [
    { step: '1／2　意味', q: '売上債権が増えたということは、何が起きているか。',
      opts: [
        { t: '売上は立ったが、まだ現金を回収していない', ok: true },
        { t: '現金がその分入ってきた' },
        { t: '値引きをして売上が減った' }],
      why: '利益には乗っているのに、現金は手元にない状態。' },
    { step: '2／2　符号', q: '符号は。',
      opts: [
        { t: '差し引く（−）', ok: true },
        { t: '足す（＋）' }],
      why: '運転資本の合言葉は「資産が増えたら−、負債が増えたら＋」。' }] });

  push({ name: '棚卸資産の減少額', amt: c.inv, sign: 1, qs: [
    { step: '符号', q: '棚卸資産が「減った」ときはどうするか。',
      opts: [
        { t: '足す（＋）／在庫が現金化された', ok: true },
        { t: '差し引く（−）／資産だから' },
        { t: '調整しない／売上原価で処理済み' }],
      why: '資産は増加なら−、減少なら＋。項目名で反射せず、必ず増減を先に読むこと。' }] });

  push({ name: '仕入債務の増加額', amt: c.ap, sign: 1, qs: [
    { step: '符号', q: '仕入債務が増えた状態をどう調整するか。',
      opts: [
        { t: '足す（＋）／仕入れたがまだ支払っていない', ok: true },
        { t: '差し引く（−）／支払義務が増えたから' },
        { t: '調整しない／負債は営業CFに無関係' }],
      why: '費用は計上済みなのに現金は手元に残っている。支払いを先送りした分だけ＋。' }] });

  push({ name: '小　計', amt: 0, sign: 1, kind: 'sub', qs: [
    { step: 'チェックポイント', q: '小計より下に並ぶのは、次のうちどれか。',
      opts: [
        { t: '利息・配当金の受取額、利息の支払額、法人税等の支払額', ok: true },
        { t: '減価償却費と引当金の増加額' },
        { t: '売上債権・棚卸資産・仕入債務の増減' },
        { t: '固定資産の取得支出と売却収入' }],
      why: '下に来るのはこの3つだけ。しかも全部「実際に動いた現金」。' }] });

  push({ name: '利息・配当金の受取額', amt: c.intRecv, sign: 1, qs: [
    { step: '符号', q: '符号は。',
      opts: [
        { t: '足す（＋）', ok: true },
        { t: '差し引く（−）' }],
      why: '実際に受け取った現金なので素直に＋。' }] });

  push({ name: '利息の支払額', amt: c.intPaid, sign: -1, qs: [
    { step: '1／2　なぜ違うか', q: '上で足し戻した支払利息 ' + c.intExp.toLocaleString() + ' と、この支払額 ' + c.intPaid.toLocaleString() + ' が一致しないのはなぜか。',
      opts: [
        { t: '未払利息があり、発生額と支払額がずれるから', ok: true },
        { t: 'どちらかが計算ミスだから' },
        { t: '受取利息と相殺されているから' }],
      why: '発生主義のPLと現金主義のCFの差。だからこそ上でキャンセルし、下で実額を出す必要がある。' },
    { step: '2／2　符号', q: '符号は。',
      opts: [
        { t: '差し引く（−）', ok: true },
        { t: '足す（＋）' }],
      why: '現金が出ていったので−。' }] });

  push({ name: '法人税等の支払額', amt: c.tax, sign: -1, qs: [
    { step: '符号', q: '符号は。',
      opts: [
        { t: '差し引く（−）', ok: true },
        { t: '足す（＋）' }],
      why: '税引前から出発した分を、ここで実際の納付額として引いて締める。' }] });

  push({ name: '営業活動によるキャッシュ・フロー', kind: 'total', auto: true, amt: 0, sign: 1 });

  if (mode === 'op') return s;

  const pushI = (o) => s.push({ sec: 'inv', ...o, qs: (o.qs || []).map(q => ({ ...q, opts: cfShuffle(q.opts) })) });

  pushI({ name: '投資活動によるキャッシュ・フロー', kind: 'sec', auto: true, amt: 0, sign: 1 });

  pushI({ name: '有形固定資産の取得による支出', amt: c.buyFix, sign: -1, qs: [
    { step: '符号', q: '設備投資の支出をどう計上するか。',
      opts: [
        { t: '差し引く（−）／投資活動', ok: true },
        { t: '差し引く（−）／営業活動' },
        { t: '減価償却費として営業CFに配分する' },
        { t: '差し引く（−）／財務活動' }],
      why: '買った期に全額が投資CFへ。営業CFで足し戻す減価償却費は、この支出を後の期に配分した会計上の費用にすぎない。' }] });

  pushI({ name: '有形固定資産の売却による収入', amt: c.sellFix, sign: 1, qs: [
    { step: '1／2　いくら載せるか', q: '簿価 ' + c.bookVal.toLocaleString() + ' の資産を売り、売却益 ' + c.gain.toLocaleString() + ' が出た。投資CFに計上する金額は。',
      opts: [
        { t: c.sellFix.toLocaleString() + '（実際に入金された売却収入の全額）', ok: true },
        { t: c.gain.toLocaleString() + '（売却益の分だけ）' },
        { t: c.bookVal.toLocaleString() + '（帳簿価額の分だけ）' },
        { t: '計上しない（営業CFで売却益を処理済み）' }],
      why: '投資CFに載るのは入金額そのもの。営業CFで売却益を引いたのは、ここで全額を計上するため。' },
    { step: '2／2　符号', q: '符号は。',
      opts: [
        { t: '足す（＋）', ok: true },
        { t: '差し引く（−）' }],
      why: '現金が入ってきたので＋。' }] });

  pushI({ name: '投資有価証券の取得による支出', amt: c.buySec, sign: -1, qs: [
    { step: '区分', q: 'この支出はどの区分か。',
      opts: [
        { t: '投資活動（−）', ok: true },
        { t: '財務活動（−）' },
        { t: '営業活動（−）' },
        { t: '現金同等物なので増減に含めない' }],
      why: '余資運用の有価証券売買は投資活動。ただし取得日から3か月以内に満期が来るものは現金同等物として扱う。' }] });

  pushI({ name: '貸付金の回収による収入', amt: c.lendBk, sign: 1, qs: [
    { step: '区分', q: '貸付金の回収はどの区分か。',
      opts: [
        { t: '投資活動（＋）／貸すのは投資', ok: true },
        { t: '財務活動（＋）／資金のやりとりだから' },
        { t: '営業活動（＋）／債権の回収だから' },
        { t: '借入金の返済と相殺する' }],
      why: '「貸す」は投資活動、「借りる」は財務活動。方向が逆になるので最も引っかかりやすい。' }] });

  pushI({ name: '投資活動によるキャッシュ・フロー', kind: 'total', auto: true, amt: 0, sign: 1 });

  const pushF = (o) => s.push({ sec: 'fin', ...o, qs: (o.qs || []).map(q => ({ ...q, opts: cfShuffle(q.opts) })) });

  pushF({ name: '財務活動によるキャッシュ・フロー', kind: 'sec', auto: true, amt: 0, sign: 1 });

  pushF({ name: '長期借入れによる収入', amt: c.borrow, sign: 1, qs: [
    { step: '区分と符号', q: '長期借入れによる収入をどう計上するか。',
      opts: [
        { t: '足す（＋）／財務活動', ok: true },
        { t: '足す（＋）／営業活動（運転資金に使うから）' },
        { t: '足す（＋）／投資活動' },
        { t: '収益ではないので計上しない' }],
      why: '財務CFは「資金をどう集め、どう返したか」。使い道が運転資金でも区分は変わらない。' }] });

  pushF({ name: '借入金の返済による支出', amt: c.repay, sign: -1, qs: [
    { step: '符号', q: '返済をどう計上するか。',
      opts: [
        { t: '差し引く（−）／収入と相殺せず総額で並べる', ok: true },
        { t: '足す（＋）／負債が減るから' },
        { t: '借入れと相殺して差額だけ計上する' }],
      why: '借入と返済は総額表示が原則。相殺すると資金繰りの実態が見えなくなる。' }] });

  pushF({ name: '株式の発行による収入', amt: c.issue, sign: 1, qs: [
    { step: '区分', q: '増資による入金はどの区分か。',
      opts: [
        { t: '財務活動（＋）', ok: true },
        { t: '投資活動（＋）' },
        { t: '営業活動（＋）' },
        { t: '資本取引なのでCFには載せない' }],
      why: '損益には出てこないが現金は実際に入ってくる。間接法の発想がそのまま効く場面。' }] });

  pushF({ name: '配当金の支払額', amt: c.divPaid, sign: -1, qs: [
    { step: '区分', q: '配当金の支払はどの区分か。',
      opts: [
        { t: '財務活動（−）／株主への払い戻し', ok: true },
        { t: '営業活動の小計より下（−）／受取配当金と同じ扱い' },
        { t: '投資活動（−）' },
        { t: '利益処分なので計上しない' }],
      why: '最頻出の混乱ポイント。受取配当金は営業CF、支払配当金は財務CF。もらうのと払うのとで区分が違う。' }] });

  pushF({ name: '財務活動によるキャッシュ・フロー', kind: 'total', auto: true, amt: 0, sign: 1 });

  return s;
}

function cfPostAuto(steps, idx, curRun, curRows, curTotals) {
  let n = idx, r = curRun;
  const rw = [...curRows], tt = [...curTotals];
  while (n < steps.length && steps[n].auto) {
    const st = steps[n];
    if (st.kind === 'sec') {
      rw.push({ ...st, display: null });
      r = 0;
    } else if (st.kind === 'total') {
      rw.push({ ...st, display: r, running: r });
      tt.push({ sec: st.sec, name: st.name, value: r });
      r = 0;
    }
    n++;
  }
  return { n, r, rw, tt };
}

function CFDrill({ onFinish, onExit }) {
  const [mode, setMode]   = useState(null);
  const [seed, setSeed]   = useState(0);
  const [cse, setCse]     = useState(null);
  const [steps, setSteps] = useState([]);

  const [i, setI]           = useState(0);
  const [qi, setQi]         = useState(0);
  const [rows, setRows]     = useState([]);
  const [run, setRun]       = useState(0);
  const [totals, setTotals] = useState([]);
  const [missed, setMissed] = useState([]);
  const [picked, setPicked] = useState([]);
  const [phase, setPhase]   = useState('ask');
  const [done, setDone]     = useState(false);
  const [reported, setReported] = useState(false);

  function begin(m) {
    const c = buildCfCase();
    const st = buildCfSteps(c, m);
    const seeded = cfPostAuto(st, 0, 0, [], []);
    setCse(c);
    setSteps(st);
    setMode(m);
    setI(seeded.n); setQi(0); setRows(seeded.rw); setRun(seeded.r); setTotals(seeded.tt);
    setMissed([]); setPicked([]); setPhase('ask'); setDone(false); setReported(false);
  }

  function again() { setSeed(seed + 1); begin(mode); }

  // ---- mode select ----
  if (!mode) {
    const card = (id, icon, title, desc, xp) => (
      <div key={id} onClick={() => begin(id)} style={{
        background: C.card, border: `1px solid ${C.border}`, borderRadius: 14,
        padding: 16, marginBottom: 12, cursor: 'pointer', display: 'flex', gap: 14, alignItems: 'center',
      }}>
        <div style={{ fontSize: 28 }}>{icon}</div>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 15, fontWeight: 700, color: C.text }}>{title}</div>
          <div style={{ fontSize: 12, color: C.muted, marginTop: 3, lineHeight: 1.6 }}>{desc}</div>
          <div style={{ fontSize: 11, color: C.gold, marginTop: 5, fontWeight: 700 }}>最大 ＋{xp} XP</div>
        </div>
      </div>
    );
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        <button onClick={onExit} style={{
          background: 'none', border: 'none', color: C.accent, cursor: 'pointer',
          fontSize: 22, padding: 0, marginBottom: 16 }}>←</button>
        <div style={{ fontSize: 19, fontWeight: 700, color: C.text, marginBottom: 6 }}>⚡ 間接法CFドリル</div>
        <div style={{ fontSize: 13, color: C.muted, marginBottom: 20, lineHeight: 1.7 }}>
          項目を1つずつ「現金は動いたか → どの活動か → だから符号は」の順で判断する。
          金額は毎回変わり、計算はドリルが積み上げます。
        </div>
        {card('op',   '💧', '営業CF（間接法）',      '税引前当期純利益から小計を経て営業CFまで。13項目。', 90)}
        {card('full', '🧾', 'フルセット（3区分）',   '営業・投資・財務の3区分をまとめて組み立てる。21項目。', 150)}
      </div>
    );
  }

  const step = steps[i];
  const q = step ? step.qs[qi] : null;

  function choose(n) {
    if (phase !== 'ask') return;
    const opt = q.opts[n];
    setPicked([...picked, n]);
    if (opt.ok) { setPhase('right'); return; }
    setMissed([...missed, step.name]);
    if (picked.length > 0) setPhase('reveal');
  }

  function next() {
    if (qi + 1 < step.qs.length) { setQi(qi + 1); setPicked([]); setPhase('ask'); return; }

    const signed = step.amt * step.sign;
    const nextRun = step.kind === 'sub' ? run : run + signed;
    const row = {
      ...step,
      display: step.kind === 'sub' ? run : signed,
      running: nextRun,
    };
    const res = cfPostAuto(steps, i + 1, nextRun, [...rows, row], totals);

    setRows(res.rw); setRun(res.r); setTotals(res.tt);
    setI(res.n); setQi(0); setPicked([]); setPhase('ask');

    if (res.n >= steps.length) finish(res.tt);
  }

  function finish(tt) {
    setDone(true);
    if (reported) return;
    setReported(true);
    const uniq = [...new Set(missed)];
    const base = mode === 'op' ? 90 : 150;
    const xp = Math.max(20, base - uniq.length * 8);
    onFinish?.({ mode, xp, missed: uniq, totals: tt });
  }

  const opTotal  = totals.find(t => t.sec === 'op')?.value ?? 0;
  const invTotal = totals.find(t => t.sec === 'inv')?.value ?? 0;
  const finTotal = totals.find(t => t.sec === 'fin')?.value ?? 0;
  const netChange = opTotal + invTotal + finTotal;
  const uniqMissed = [...new Set(missed)];

  return (
    <div style={{ padding: '16px 16px 80px' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14 }}>
        <button onClick={() => setMode(null)} style={{
          background: 'none', border: 'none', color: C.accent, cursor: 'pointer',
          fontSize: 22, padding: 0 }}>←</button>
        <div style={{ flex: 1, fontSize: 15, fontWeight: 700, color: C.text }}>
          {mode === 'op' ? '営業CF（間接法）' : 'フルセット（3区分）'}
        </div>
        <div style={{ fontSize: 12, color: C.muted }}>単位：万円</div>
      </div>

      {/* 進捗 */}
      <div style={{ display: 'flex', gap: 3, marginBottom: 14 }}>
        {steps.filter(x => !x.auto).map((x, n) => {
          const idx = steps.filter(y => !y.auto).indexOf(x);
          const cur = steps.filter(y => !y.auto).findIndex(y => y === step);
          return (
            <div key={n} style={{
              flex: 1, height: 3, borderRadius: 2,
              background: idx < cur || done ? C.green : idx === cur ? C.gold : C.border,
            }} />
          );
        })}
      </div>

      {/* 台帳 */}
      <div style={{
        background: C.card, border: `1px solid ${C.border}`, borderRadius: 14,
        padding: '6px 0', marginBottom: 16, maxHeight: 300, overflowY: 'auto',
      }}>
        {rows.length === 0 && (
          <div style={{ color: C.muted, fontSize: 12, padding: '12px 14px' }}>
            判断した項目から順に、ここへ積み上がります。
          </div>
        )}
        {rows.map((r, n) => {
          const col = CF_SEC[r.sec] || C.accent;
          if (r.kind === 'sec') {
            return (
              <div key={n} style={{
                padding: '8px 14px 6px', fontSize: 12, fontWeight: 700, color: col,
                borderBottom: `1px solid ${C.border}`,
              }}>{r.name}</div>
            );
          }
          const isTotal = r.kind === 'total';
          const isSub   = r.kind === 'sub';
          const isHead  = r.kind === 'head';
          return (
            <div key={n} style={{
              display: 'grid', gridTemplateColumns: '1fr auto auto', gap: 10,
              alignItems: 'baseline', padding: '6px 14px', fontSize: 13,
              background: isTotal ? col + '1f' : isSub ? '#0d1117' : 'transparent',
              borderTop: isSub || isTotal ? `1px solid ${C.border}` : 'none',
              fontWeight: isTotal || isSub ? 700 : 400,
            }}>
              <span style={{ color: isTotal ? col : C.text }}>{r.name}</span>
              <span style={{
                fontSize: isTotal ? 16 : 14, fontWeight: 700,
                color: isTotal ? col : isSub || isHead ? C.text
                  : r.display >= 0 ? C.green : C.red,
              }}>
                {isTotal || isSub || isHead
                  ? Number(r.display).toLocaleString()
                  : cfSigned(r.display)}
              </span>
              <span style={{ fontSize: 11, color: C.muted, minWidth: 60, textAlign: 'right' }}>
                {isTotal || isSub ? '' : Number(r.running).toLocaleString()}
              </span>
            </div>
          );
        })}
      </div>

      {/* 結果 */}
      {done ? (
        <div style={{
          background: C.card, border: `1px solid ${C.border}`, borderRadius: 16, padding: '24px 18px',
        }}>
          <div style={{ textAlign: 'center', marginBottom: 18 }}>
            <div style={{ fontSize: 40, marginBottom: 8 }}>{uniqMissed.length === 0 ? '🎉' : '📝'}</div>
            <div style={{ fontSize: 13, color: C.muted }}>
              {mode === 'op' ? '営業活動によるキャッシュ・フロー' : '現金及び現金同等物の増加額'}
            </div>
            <div style={{
              fontSize: 32, fontWeight: 700, marginTop: 2,
              color: uniqMissed.length === 0 ? C.gold : C.accent,
            }}>
              {(mode === 'op' ? opTotal : netChange).toLocaleString()}
            </div>
          </div>

          {mode !== 'op' && (
            <div style={{
              background: '#0d1117', borderRadius: 10, padding: '12px 14px',
              marginBottom: 14, fontSize: 13,
            }}>
              {[['営業CF', opTotal, CF_SEC.op], ['投資CF', invTotal, CF_SEC.inv], ['財務CF', finTotal, CF_SEC.fin]].map(([label, v, col]) => (
                <div key={label} style={{ display: 'flex', justifyContent: 'space-between', padding: '3px 0' }}>
                  <span style={{ color: col, fontWeight: 700 }}>{label}</span>
                  <span style={{ color: v >= 0 ? C.green : C.red, fontWeight: 700 }}>{cfSigned(v)}</span>
                </div>
              ))}
              <div style={{
                display: 'flex', justifyContent: 'space-between', padding: '8px 0 0',
                marginTop: 6, borderTop: `1px solid ${C.border}`,
              }}>
                <span style={{ color: C.muted }}>期首残高 {cse.opening.toLocaleString()} → 期末残高</span>
                <span style={{ color: C.text, fontWeight: 700 }}>{(cse.opening + netChange).toLocaleString()}</span>
              </div>
            </div>
          )}

          <div style={{
            background: '#0d1117', borderRadius: 10, padding: '12px 14px',
            marginBottom: 18, fontSize: 13, color: C.text, lineHeight: 1.7,
          }}>
            {uniqMissed.length === 0
              ? '全項目ノーミス。次は数字を変えて、迷わず符号が出るかを試してください。'
              : (<>つまずいた項目
                  <ul style={{ margin: '6px 0 0', paddingLeft: 18, color: C.muted }}>
                    {uniqMissed.map(m => <li key={m} style={{ margin: '3px 0' }}>{m}</li>)}
                  </ul>
                </>)}
          </div>

          <div style={{ display: 'flex', gap: 10 }}>
            <button onClick={again} style={{
              flex: 1, padding: '13px', borderRadius: 10, border: `1px solid ${C.accent}`,
              background: 'transparent', color: C.accent, fontWeight: 700, cursor: 'pointer', fontSize: 14,
            }}>別の数字でもう一度</button>
            <button onClick={() => setMode(null)} style={{
              flex: 1, padding: '13px', borderRadius: 10, border: 'none',
              background: C.accent, color: '#000', fontWeight: 700, cursor: 'pointer', fontSize: 14,
            }}>ドリル一覧へ</button>
          </div>
        </div>
      ) : step && q ? (
        <div style={{
          background: C.card, border: `1px solid ${C.border}`,
          borderLeft: `3px solid ${CF_SEC[step.sec]}`, borderRadius: 14, padding: '16px 15px',
        }}>
          <div style={{
            display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 12,
            paddingBottom: 12, marginBottom: 14, borderBottom: `1px dashed ${C.border}`,
          }}>
            <span style={{ fontSize: 16, fontWeight: 700, color: C.text }}>{step.name}</span>
            {step.kind !== 'sub' && (
              <span style={{ fontSize: 16, fontWeight: 700, color: C.gold }}>
                {step.amt.toLocaleString()}
              </span>
            )}
          </div>

          <div style={{ fontSize: 11, color: C.muted, marginBottom: 6 }}>{q.step}</div>
          <div style={{ fontSize: 15, fontWeight: 600, color: C.text, marginBottom: 14, lineHeight: 1.6 }}>{q.q}</div>

          {q.opts.map((o, n) => {
            const wrong = picked.includes(n) && !o.ok;
            const right = (phase === 'right' && picked.includes(n) && o.ok) || (phase === 'reveal' && o.ok);
            return (
              <button key={n} onClick={() => choose(n)} disabled={phase !== 'ask' || wrong}
                style={{
                  display: 'block', width: '100%', textAlign: 'left',
                  padding: '12px 13px', marginBottom: 8, borderRadius: 10,
                  border: `1px solid ${right ? C.green : wrong ? C.red : C.border}`,
                  background: right ? C.green + '1f' : wrong ? C.red + '18' : '#0d1117',
                  color: C.text, fontSize: 14, lineHeight: 1.55,
                  cursor: phase === 'ask' && !wrong ? 'pointer' : 'default',
                  fontFamily: 'inherit',
                }}>{o.t}</button>
            );
          })}

          {phase === 'ask' && picked.length > 0 && (
            <div style={{
              marginTop: 12, padding: '12px 13px', borderRadius: 10,
              background: C.red + '14', border: `1px solid ${C.red}44`, fontSize: 13, color: C.text,
            }}>
              ちがいます。現金が実際に動いたかどうかで、もう一度考えてみてください。
            </div>
          )}

          {(phase === 'right' || phase === 'reveal') && (
            <>
              <div style={{
                marginTop: 12, padding: '12px 13px', borderRadius: 10,
                background: phase === 'right' ? C.green + '14' : C.red + '14',
                border: `1px solid ${phase === 'right' ? C.green : C.red}44`,
                fontSize: 13, color: C.text, lineHeight: 1.7,
              }}>
                <div style={{
                  fontWeight: 700, marginBottom: 3,
                  color: phase === 'right' ? C.green : C.red,
                }}>{phase === 'right' ? 'そのとおり' : '正解はこちら'}</div>
                {q.why}
              </div>
              <button onClick={next} style={{
                marginTop: 12, width: '100%', padding: 13, borderRadius: 10, border: 'none',
                background: phase === 'right' ? C.accent : C.border,
                color: phase === 'right' ? '#000' : C.text,
                fontWeight: 700, fontSize: 15, cursor: 'pointer', fontFamily: 'inherit',
              }}>
                {qi + 1 < step.qs.length ? '次の分岐へ' : '台帳に記入する'}
              </button>
            </>
          )}
        </div>
      ) : null}
    </div>
  );
}

function FinanceTab({ data, onFinanceComplete, onCaseStudyComplete, onDrillComplete }) {
  const [view, setView]                   = useState('list');
  const [selectedCase, setSelectedCase]   = useState('case4');
  const [filterType, setFilterType]           = useState('all');
  const [filterDifficulty, setFilterDifficulty] = useState('all');
  const [activeProblem, setActiveProblem] = useState(null);
  const [currentStep, setCurrentStep]     = useState(0);
  const [selectedChoice, setSelectedChoice] = useState(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [stepResults, setStepResults]     = useState([]);
  const [solverDone, setSolverDone]       = useState(false);
  const [tabMode, setTabMode]             = useState('study');
  const [expandedTopic, setExpandedTopic] = useState(null);
  const [cardSession, setCardSession]     = useState(null);

  function resetSolver() {
    setCurrentStep(0);
    setSelectedChoice(null);
    setShowExplanation(false);
    setStepResults([]);
    setSolverDone(false);
  }

  function shuffleProblem(problem) {
    const steps = problem.steps.map(step => {
      const items = step.choices.map((c, i) => ({ c, isCorrect: i === step.correct }));
      for (let i = items.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [items[i], items[j]] = [items[j], items[i]];
      }
      return { ...step, choices: items.map(x => x.c), correct: items.findIndex(x => x.isCorrect) };
    });
    return { ...problem, steps };
  }

  function startProblem(problem) {
    setActiveProblem(shuffleProblem(problem));
    resetSolver();
    setView('solver');
  }

  function handleChoiceSelect(idx) {
    if (selectedChoice !== null) return;
    setSelectedChoice(idx);
    setShowExplanation(true);
  }

  function handleNext() {
    const isCorrect = selectedChoice === activeProblem.steps[currentStep].correct;
    const newResults = [...stepResults, isCorrect];
    if (currentStep + 1 >= activeProblem.steps.length) {
      setStepResults(newResults);
      setSolverDone(true);
      if (activeProblem.case && activeProblem.case !== 'case4') {
        onCaseStudyComplete(activeProblem.id, newResults.filter(Boolean).length, activeProblem.steps.length);
      } else {
        onFinanceComplete(activeProblem.id, newResults.filter(Boolean).length, activeProblem.steps.length);
      }
    } else {
      setStepResults(newResults);
      setCurrentStep(s => s + 1);
      setSelectedChoice(null);
      setShowExplanation(false);
    }
  }

  function getProblemProgress(problemId, isCaseStudy) {
    const store = isCaseStudy ? data.caseProgress : data.financeProgress;
    return store?.[problemId] || { attempts: 0, bestCorrect: 0, completed: false };
  }

  const filterTypes = [
    { id: 'all', label: 'すべて' },
    { id: 'cvp', label: 'CVP分析' },
    { id: 'npv', label: 'NPV分析' },
    { id: 'ratio', label: '財務比率' },
    { id: 'cashflow', label: 'CF計算' },
  ];
  const caseSelectors = [
    { id: 'case1', label: '事例I', sub: '人事・組織' },
    { id: 'case2', label: '事例II', sub: 'マーケ' },
    { id: 'case3', label: '事例III', sub: '生産' },
    { id: 'case4', label: '事例IV', sub: '財務' },
  ];
  const caseTitles = {
    case1: '事例I 人事・組織', case2: '事例II マーケティング',
    case3: '事例III 生産・技術', case4: '事例IV 財務計算',
  };
  const isCaseStudy = selectedCase !== 'case4';
  const sourceProblems = isCaseStudy
    ? CASE_STUDY_PROBLEMS.filter(p => p.case === selectedCase)
    : FINANCE_PROBLEMS;
  const filtered = sourceProblems.filter(p => {
    if (!isCaseStudy && filterType !== 'all' && p.type !== filterType) return false;
    const diffOk = filterDifficulty === 'all' || (p.difficulty || '基礎') === filterDifficulty;
    return diffOk;
  });

  // ---- List view ----
  if (view === 'drill') {
    return <CFDrill onFinish={onDrillComplete} onExit={() => setView('list')} />;
  }

  if (view === 'list') {
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        {/* Mode toggle */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
          {[
            { id: 'study', label: '✍️ 演習' },
            { id: 'textbook', label: '📖 テキスト' },
          ].map(m => (
            <button
              key={m.id}
              onClick={() => { setTabMode(m.id); setCardSession(null); setExpandedTopic(null); }}
              style={{
                padding: '8px 20px', borderRadius: 20, border: 'none',
                background: tabMode === m.id ? C.accent : C.card,
                color: tabMode === m.id ? '#000' : C.muted,
                fontWeight: tabMode === m.id ? 700 : 400,
                cursor: 'pointer', fontSize: 13,
              }}
            >{m.label}</button>
          ))}
        </div>

        {tabMode === 'textbook' && (() => {
          const topics = TEXTBOOK_CONTENT[selectedCase] || [];

          // カードセッション中のフラッシュカードビュー
          if (cardSession) {
            const card = cardSession.cards[cardSession.index];
            return (
              <div>
                {/* Case selector (共通) */}
                <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
                  {caseSelectors.map(cs => (
                    <button
                      key={cs.id}
                      onClick={() => { setSelectedCase(cs.id); setCardSession(null); setExpandedTopic(null); }}
                      style={{
                        padding: '6px 12px', borderRadius: 20, border: 'none',
                        background: selectedCase === cs.id ? C.purple : C.card,
                        color: selectedCase === cs.id ? '#fff' : C.muted,
                        fontWeight: selectedCase === cs.id ? 700 : 400,
                        cursor: 'pointer', fontSize: 12,
                      }}
                    >{cs.label} <span style={{ fontSize: 10, opacity: 0.75 }}>{cs.sub}</span></button>
                  ))}
                </div>

                {/* Back button & counter */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                  <button
                    onClick={() => setCardSession(null)}
                    style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 14, padding: 0 }}
                  >← テキストに戻る</button>
                  <span style={{ color: C.muted, fontSize: 13 }}>
                    {cardSession.index + 1} / {cardSession.cards.length}
                  </span>
                </div>

                {/* Topic title */}
                <div style={{ fontSize: 15, fontWeight: 700, color: C.text, marginBottom: 12 }}>
                  {topics.find(t => t.id === cardSession.topicId)?.icon} {topics.find(t => t.id === cardSession.topicId)?.title}
                </div>

                {/* Card */}
                <div
                  onClick={() => setCardSession(s => ({ ...s, flipped: !s.flipped }))}
                  style={{
                    background: cardSession.flipped ? '#1a1040' : C.card,
                    border: `1px solid ${cardSession.flipped ? C.purple : '#334155'}`,
                    borderRadius: 16, padding: 28, minHeight: 160,
                    display: 'flex', flexDirection: 'column', justifyContent: 'center',
                    cursor: 'pointer', transition: 'all 0.2s', marginBottom: 20,
                  }}
                >
                  {!cardSession.flipped ? (
                    <>
                      <div style={{ fontSize: 16, fontWeight: 700, color: C.text, marginBottom: 16, lineHeight: 1.5 }}>
                        {card.front}
                      </div>
                      <div style={{ fontSize: 12, color: C.muted, textAlign: 'center' }}>タップして答えを確認 →</div>
                    </>
                  ) : (
                    <>
                      <div style={{ fontSize: 11, color: C.purple, marginBottom: 8, fontWeight: 600 }}>答え</div>
                      <div style={{ fontSize: 15, color: C.text, lineHeight: 1.7, whiteSpace: 'pre-line' }}>
                        {card.back}
                      </div>
                    </>
                  )}
                </div>

                {/* Prev / Next */}
                <div style={{ display: 'flex', gap: 12 }}>
                  <button
                    onClick={() => setCardSession(s => ({ ...s, index: Math.max(0, s.index - 1), flipped: false }))}
                    disabled={cardSession.index === 0}
                    style={{
                      flex: 1, padding: '12px', borderRadius: 12, border: 'none',
                      background: cardSession.index === 0 ? '#1e293b' : C.card,
                      color: cardSession.index === 0 ? C.muted : C.text,
                      cursor: cardSession.index === 0 ? 'default' : 'pointer', fontSize: 14,
                    }}
                  >← 前へ</button>
                  <button
                    onClick={() => setCardSession(s => ({
                      ...s,
                      index: Math.min(s.cards.length - 1, s.index + 1),
                      flipped: false,
                    }))}
                    disabled={cardSession.index === cardSession.cards.length - 1}
                    style={{
                      flex: 1, padding: '12px', borderRadius: 12, border: 'none',
                      background: cardSession.index === cardSession.cards.length - 1 ? '#1e293b' : C.accent,
                      color: cardSession.index === cardSession.cards.length - 1 ? C.muted : '#000',
                      cursor: cardSession.index === cardSession.cards.length - 1 ? 'default' : 'pointer',
                      fontSize: 14, fontWeight: 700,
                    }}
                  >次へ →</button>
                </div>
              </div>
            );
          }

          // テキスト参考書ビュー（アコーディオン）
          return (
            <div>
              {/* Case selector */}
              <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
                {caseSelectors.map(cs => (
                  <button
                    key={cs.id}
                    onClick={() => { setSelectedCase(cs.id); setExpandedTopic(null); }}
                    style={{
                      padding: '6px 12px', borderRadius: 20, border: 'none',
                      background: selectedCase === cs.id ? C.purple : C.card,
                      color: selectedCase === cs.id ? '#fff' : C.muted,
                      fontWeight: selectedCase === cs.id ? 700 : 400,
                      cursor: 'pointer', fontSize: 12,
                    }}
                  >{cs.label} <span style={{ fontSize: 10, opacity: 0.75 }}>{cs.sub}</span></button>
                ))}
              </div>

              {topics.map(topic => {
                const isOpen = expandedTopic === topic.id;
                return (
                  <div
                    key={topic.id}
                    style={{
                      background: C.card, borderRadius: 12, marginBottom: 10,
                      border: `1px solid ${isOpen ? C.accent + '44' : '#1e293b'}`,
                      overflow: 'hidden',
                    }}
                  >
                    {/* Header */}
                    <button
                      onClick={() => setExpandedTopic(isOpen ? null : topic.id)}
                      style={{
                        width: '100%', background: 'none', border: 'none',
                        padding: '14px 16px', display: 'flex', alignItems: 'flex-start',
                        gap: 12, cursor: 'pointer', textAlign: 'left',
                      }}
                    >
                      <span style={{ fontSize: 22 }}>{topic.icon}</span>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{topic.title}</div>
                        <div style={{ fontSize: 12, color: C.muted, marginTop: 3 }}>{topic.summary}</div>
                      </div>
                      <span style={{ color: C.muted, fontSize: 16, marginTop: 2 }}>{isOpen ? '▲' : '▼'}</span>
                    </button>

                    {/* Body */}
                    {isOpen && (
                      <div style={{ padding: '0 16px 16px' }}>
                        <div style={{
                          fontSize: 13, color: '#cbd5e1', lineHeight: 1.8,
                          whiteSpace: 'pre-line', marginBottom: 12,
                          borderTop: '1px solid #1e293b', paddingTop: 12,
                        }}>
                          {topic.body}
                        </div>
                        {topic.mnemonic && (
                          <div style={{
                            background: '#1a1040', borderRadius: 8, padding: '10px 12px',
                            marginBottom: 12, border: `1px solid ${C.purple}44`,
                          }}>
                            <span style={{ fontSize: 11, color: C.purple, fontWeight: 700 }}>💡 覚え方 </span>
                            <span style={{ fontSize: 12, color: '#c4b5fd' }}>{topic.mnemonic}</span>
                          </div>
                        )}
                        <button
                          onClick={() => setCardSession({
                            topicId: topic.id,
                            cards: topic.cards,
                            index: 0,
                            flipped: false,
                          })}
                          style={{
                            width: '100%', padding: '10px', borderRadius: 10,
                            background: C.accent + '22', color: C.accent,
                            cursor: 'pointer', fontSize: 13, fontWeight: 700,
                            border: `1px solid ${C.accent}44`,
                          }}
                        >🃏 カードで確認 ({topic.cards.length}枚) →</button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          );
        })()}

        {tabMode === 'study' && (
          <>
            <div style={{ fontSize: 18, fontWeight: 700, color: C.text, marginBottom: 2 }}>
              {caseTitles[selectedCase]}
            </div>
            <div style={{ fontSize: 13, color: C.muted, marginBottom: 12 }}>ステップ別選択問題</div>

            {!isCaseStudy && (
              <div
                onClick={() => setView('drill')}
                style={{
                  background: `linear-gradient(135deg, ${C.accent}22, ${C.purple}22)`,
                  border: `1px solid ${C.accent}66`, borderRadius: 14,
                  padding: '14px 16px', marginBottom: 16, cursor: 'pointer',
                  display: 'flex', alignItems: 'center', gap: 14,
                }}
              >
                <div style={{ fontSize: 26 }}>⚡</div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 15, fontWeight: 700, color: C.text }}>間接法CFドリル</div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 3, lineHeight: 1.6 }}>
                    数字が毎回変わる。符号を判断すると台帳が積み上がります
                  </div>
                </div>
                <div style={{ fontSize: 18, color: C.accent }}>›</div>
              </div>
            )}

            {/* Case selector */}
            <div style={{ display: 'flex', gap: 6, marginBottom: 14, flexWrap: 'wrap' }}>
              {caseSelectors.map(cs => (
                <button
                  key={cs.id}
                  onClick={() => { setSelectedCase(cs.id); setFilterType('all'); setFilterDifficulty('all'); }}
                  style={{
                    padding: '6px 12px', borderRadius: 20, border: 'none',
                    background: selectedCase === cs.id ? C.purple : C.card,
                    color: selectedCase === cs.id ? '#fff' : C.muted,
                    fontWeight: selectedCase === cs.id ? 700 : 400,
                    cursor: 'pointer', fontSize: 12,
                  }}
                >{cs.label} <span style={{ fontSize: 10, opacity: 0.75 }}>{cs.sub}</span></button>
              ))}
            </div>

            {/* Type filter (case4 only) */}
            {!isCaseStudy && (
            <div style={{ display: 'flex', gap: 6, marginBottom: 8, flexWrap: 'wrap' }}>
              {filterTypes.map(ft => (
                <button
                  key={ft.id}
                  onClick={() => setFilterType(ft.id)}
                  style={{
                    padding: '6px 12px', borderRadius: 20, border: 'none',
                    background: filterType === ft.id ? C.accent : C.card,
                    color: filterType === ft.id ? '#000' : C.muted,
                    fontWeight: filterType === ft.id ? 700 : 400,
                    cursor: 'pointer', fontSize: 12,
                  }}
                >{ft.label}</button>
              ))}
            </div>
            )}

            {/* Difficulty filter */}
            <div style={{ display: 'flex', gap: 6, marginBottom: 16 }}>
              {[
                { id: 'all', label: 'すべて' },
                { id: '基礎', label: '⭐ 基礎' },
                { id: '応用', label: '⭐⭐ 応用' },
              ].map(df => (
                <button
                  key={df.id}
                  onClick={() => setFilterDifficulty(df.id)}
                  style={{
                    padding: '5px 12px', borderRadius: 20, border: 'none',
                    background: filterDifficulty === df.id ? C.gold : C.card,
                    color: filterDifficulty === df.id ? '#000' : C.muted,
                    fontWeight: filterDifficulty === df.id ? 700 : 400,
                    cursor: 'pointer', fontSize: 12,
                  }}
                >{df.label}</button>
              ))}
            </div>

            {/* Problem cards */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {filtered.map(p => {
                const prog = getProblemProgress(p.id, isCaseStudy);
                const typeColor = (isCaseStudy ? CASE_TYPE_COLORS : FINANCE_TYPE_COLORS)[p.type] || C.muted;
                const typeLabel = (isCaseStudy ? CASE_TYPE_LABELS : FINANCE_TYPE_LABELS)[p.type];
                return (
                  <div
                    key={p.id}
                    onClick={() => startProblem(p)}
                    style={{
                      background: prog.completed ? '#0a1f0a' : C.card,
                      border: `1px solid ${prog.completed ? C.green + '66' : C.border}`,
                      borderRadius: 14, padding: '14px 16px',
                      cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 12,
                    }}
                  >
                    <div style={{ fontSize: 26 }}>{p.icon}</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 4 }}>
                        <span style={{
                          fontSize: 10, fontWeight: 700, color: typeColor,
                          background: typeColor + '22', borderRadius: 4, padding: '2px 6px',
                        }}>{typeLabel}</span>
                        {p.difficulty === '応用' && (
                          <span style={{
                            fontSize: 10, fontWeight: 700, color: C.gold,
                            background: C.gold + '22', borderRadius: 4, padding: '2px 6px',
                          }}>⭐⭐ 応用</span>
                        )}
                      </div>
                      <div style={{ fontSize: 14, fontWeight: 600, color: C.text }}>{p.title}</div>
                      <div style={{ fontSize: 11, color: C.muted, marginTop: 2 }}>
                        {p.steps.length}ステップ · ＋{p.xp} XP
                      </div>
                    </div>
                    <div style={{ textAlign: 'right', flexShrink: 0 }}>
                      {prog.completed ? (
                        <div style={{ fontSize: 22, color: C.green }}>✓</div>
                      ) : prog.attempts > 0 ? (
                        <div style={{ fontSize: 12, color: C.muted }}>
                          {prog.bestCorrect}/{p.steps.length}
                        </div>
                      ) : (
                        <div style={{ width: 20, height: 20, borderRadius: '50%', border: `2px solid ${C.border}` }} />
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </>
        )}
      </div>
    );
  }

  const step = activeProblem?.steps[currentStep];
  const totalSteps = activeProblem?.steps.length || 0;

  // ---- Completion screen ----
  if (solverDone) {
    const correctCount = stepResults.filter(Boolean).length;
    const perfect = correctCount === totalSteps;
    return (
      <div style={{ padding: '16px 16px 80px' }}>
        <button
          onClick={() => { setView('list'); resetSolver(); setActiveProblem(null); }}
          style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0, marginBottom: 20 }}
        >←</button>
        <div style={{
          textAlign: 'center', padding: '32px 20px',
          background: C.card, borderRadius: 16, border: `1px solid ${C.border}`,
        }}>
          <div style={{ fontSize: 48, marginBottom: 12 }}>{perfect ? '🎉' : '📝'}</div>
          <div style={{ fontSize: 20, fontWeight: 700, color: perfect ? C.gold : C.text, marginBottom: 8 }}>
            {perfect ? '全問正解！' : '結果'}
          </div>
          <div style={{ fontSize: 36, fontWeight: 700, color: perfect ? C.gold : C.accent, marginBottom: 4 }}>
            {correctCount} / {totalSteps}
          </div>
          <div style={{ fontSize: 13, color: C.muted, marginBottom: 24 }}>
            {perfect ? `＋${activeProblem.xp} XP 獲得！` : `＋${correctCount * activeProblem.partialXp} XP 獲得`}
          </div>
          <div style={{ display: 'flex', justifyContent: 'center', gap: 8, marginBottom: 28 }}>
            {stepResults.map((ok, i) => (
              <div key={i} style={{
                width: 34, height: 34, borderRadius: '50%',
                background: ok ? C.green : C.red,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 16, color: '#fff', fontWeight: 700,
              }}>{ok ? '✓' : '✗'}</div>
            ))}
          </div>
          <div style={{ display: 'flex', gap: 10, justifyContent: 'center' }}>
            <button
              onClick={() => startProblem(activeProblem)}
              style={{
                padding: '12px 20px', borderRadius: 10, border: `1px solid ${C.accent}`,
                background: 'transparent', color: C.accent,
                fontWeight: 700, cursor: 'pointer', fontSize: 14,
              }}
            >もう一度</button>
            <button
              onClick={() => { setView('list'); resetSolver(); setActiveProblem(null); }}
              style={{
                padding: '12px 20px', borderRadius: 10, border: 'none',
                background: C.accent, color: '#000',
                fontWeight: 700, cursor: 'pointer', fontSize: 14,
              }}
            >問題一覧へ</button>
          </div>
        </div>
      </div>
    );
  }

  // ---- Solver view ----
  return (
    <div style={{ padding: '16px 16px 80px' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16 }}>
        <button
          onClick={() => { setView('list'); resetSolver(); setActiveProblem(null); }}
          style={{ background: 'none', border: 'none', color: C.accent, cursor: 'pointer', fontSize: 22, padding: 0 }}
        >←</button>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 14, fontWeight: 700, color: C.text }}>{activeProblem?.title}</div>
          <div style={{ fontSize: 12, color: C.muted }}>Step {currentStep + 1} / {totalSteps}</div>
        </div>
      </div>

      {/* Progress bar */}
      <div style={{ height: 4, background: C.border, borderRadius: 2, marginBottom: 16 }}>
        <div style={{
          height: '100%', width: `${(currentStep / totalSteps) * 100}%`,
          background: C.accent, borderRadius: 2, transition: 'width 0.3s',
        }} />
      </div>

      {/* Problem intro */}
      <div style={{
        background: C.purple + '11', border: `1px solid ${C.purple}33`,
        borderRadius: 12, padding: 14, marginBottom: 16,
        fontSize: 13, color: C.text, lineHeight: 1.7,
      }}>
        <div style={{ fontSize: 11, color: C.purple, fontWeight: 700, marginBottom: 6 }}>問題文</div>
        {activeProblem?.intro}
      </div>

      {/* Step question */}
      <div style={{
        background: C.card, border: `1px solid ${C.accent}44`,
        borderRadius: 12, padding: 16, marginBottom: 16,
      }}>
        <div style={{ fontSize: 14, fontWeight: 600, color: C.text, lineHeight: 1.7 }}>
          {step?.question}
        </div>
      </div>

      {/* Choices */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 16 }}>
        {step?.choices.map((choice, idx) => {
          let bg = C.card, border = C.border, color = C.text;
          if (selectedChoice !== null) {
            if (idx === step.correct) {
              bg = C.green + '22'; border = C.green; color = C.green;
            } else if (idx === selectedChoice) {
              bg = C.red + '22'; border = C.red; color = C.red;
            } else {
              color = C.muted;
            }
          }
          return (
            <button
              key={idx}
              onClick={() => handleChoiceSelect(idx)}
              disabled={selectedChoice !== null}
              style={{
                background: bg, border: `1px solid ${border}`,
                borderRadius: 10, padding: '12px 14px',
                color, textAlign: 'left',
                cursor: selectedChoice === null ? 'pointer' : 'default',
                fontSize: 13, lineHeight: 1.5,
                fontWeight: idx === step.correct && selectedChoice !== null ? 700 : 400,
                transition: 'all 0.2s',
              }}
            ><span style={{ fontWeight: 700, marginRight: 6 }}>{['A','B','C','D'][idx]}.</span>{choice}</button>
          );
        })}
      </div>

      {/* Explanation */}
      {showExplanation && (
        <div style={{
          background: selectedChoice === step.correct ? C.green + '11' : C.red + '11',
          border: `1px solid ${selectedChoice === step.correct ? C.green + '44' : C.red + '44'}`,
          borderRadius: 12, padding: 14, marginBottom: 16,
          fontSize: 13, color: C.text, lineHeight: 1.7,
        }}>
          <div style={{
            fontSize: 11, fontWeight: 700, marginBottom: 6,
            color: selectedChoice === step.correct ? C.green : C.red,
          }}>
            {selectedChoice === step.correct ? '✓ 正解！' : '✗ 不正解'}
          </div>
          {step?.explanation}
        </div>
      )}

      {/* Next button */}
      {showExplanation && (
        <button
          onClick={handleNext}
          style={{
            width: '100%', padding: 14,
            background: `linear-gradient(135deg, ${C.purple}, ${C.accent})`,
            border: 'none', borderRadius: 12,
            color: '#fff', fontWeight: 700, fontSize: 15, cursor: 'pointer',
          }}
        >
          {currentStep + 1 >= totalSteps ? '結果を見る →' : '次へ →'}
        </button>
      )}
    </div>
  );
}

// ============================================================
// BottomNav
// ============================================================

function BottomNav({ active, onChange, remainingCount }) {
  const tabs = [
    { id: 'quest',      label: 'クエスト', icon: '⚔️' },
    { id: 'procedure',  label: '手順',     icon: '📋' },
    { id: 'reflection', label: '振り返り', icon: '📝' },
    { id: 'history',    label: '履歴',     icon: '📜' },
    { id: 'finance',    label: '演習',     icon: '📚' },
  ];

  return (
    <div style={{
      position: 'fixed', bottom: 0, left: 0, right: 0,
      background: '#0d1117', borderTop: `1px solid ${C.border}`,
      display: 'flex', height: 60,
      maxWidth: 480, margin: '0 auto',
    }}>
      {tabs.map(tab => (
        <button
          key={tab.id}
          onClick={() => onChange(tab.id)}
          style={{
            flex: 1, display: 'flex', flexDirection: 'column',
            alignItems: 'center', justifyContent: 'center', gap: 2,
            background: 'none', border: 'none', cursor: 'pointer',
            color: active === tab.id ? C.accent : C.muted,
            borderTop: active === tab.id ? `2px solid ${C.accent}` : '2px solid transparent',
          }}
        >
          <div style={{ position: 'relative', display: 'inline-flex' }}>
            <span style={{ fontSize: 18 }}>{tab.icon}</span>
            {tab.id === 'quest' && remainingCount > 0 && (
              <div style={{
                position: 'absolute', top: -4, right: -8,
                background: C.red, borderRadius: '50%',
                minWidth: 16, height: 16, padding: '0 2px',
                fontSize: 10, fontWeight: 700, color: '#fff',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
              }}>
                {remainingCount}
              </div>
            )}
          </div>
          <span style={{ fontSize: 9, fontWeight: active === tab.id ? 700 : 400 }}>
            {tab.label}
          </span>
        </button>
      ))}
    </div>
  );
}

// ============================================================
// App
// ============================================================

export default function App() {
  const [tab,      setTab]      = useState('quest');
  const [data,     setData]     = useState(() => applyDateReset(loadData()));
  const [reward,   setReward]   = useState(null);
  const [particles, setParticles] = useState(null);
  const [levelUp,  setLevelUp]  = useState(null);

  function commit(newData) {
    setData(newData);
    saveData(newData);
  }

  function buildHistoryItem(icon, name, xp, elapsed) {
    const item = { icon, name, xp, time: formatDateTime() };
    if (elapsed != null && elapsed > 0) item.elapsed = elapsed;
    return item;
  }

  function applyXpGain(base, xp, historyItem) {
    const today     = todayStr();
    const weekStart = getWeekStart();
    const dayIdx    = getDayIndex();
    let d = { ...base };

    if (d.weekStart !== weekStart) {
      const currentWeekXp = (d.weeklyXpData || []).reduce((a, b) => a + b, 0);
      if (currentWeekXp > 0) {
        const wh = [...(d.weeklyXpHistory || []), currentWeekXp];
        d.weeklyXpHistory = wh.slice(-8);
      }
      d.weeklyData   = [0, 0, 0, 0, 0, 0, 0];
      d.weeklyXpData = [0, 0, 0, 0, 0, 0, 0];
      d.weekStart    = weekStart;
    }
    if (d.lastDate !== today) {
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      d.streak = d.lastDate === localDateStr(yesterday) ? (d.streak || 0) + 1 : 0;
      d.completedToday = [];
    }

    d.xp         = (d.xp || 0) + xp;
    d.totalTasks = (d.totalTasks || 0) + 1;
    d.lastDate   = today;

    const weekly = [...(d.weeklyData || [0, 0, 0, 0, 0, 0, 0])];
    weekly[dayIdx] = (weekly[dayIdx] || 0) + 1;
    d.weeklyData = weekly;

    const xpData = [...(d.weeklyXpData || [0, 0, 0, 0, 0, 0, 0])];
    xpData[dayIdx] = (xpData[dayIdx] || 0) + xp;
    d.weeklyXpData = xpData;

    const hist = [...(d.history || []), historyItem];
    d.history = hist.length > 40 ? hist.slice(-40) : hist;

    const prevDay = (d.dailyLog || {})[today] || { tasks: 0, xp: 0 };
    d.dailyLog = { ...(d.dailyLog || {}), [today]: { tasks: prevDay.tasks + 1, xp: prevDay.xp + xp } };

    return d;
  }

  function handleCompleteQuest(quest, elapsed) {
    if (data.completedToday.includes(quest.id)) return;
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem(quest.icon, quest.name, quest.xp, elapsed);
    let d = applyXpGain(data, quest.xp, hi);
    d.completedToday = [...(d.completedToday || []), quest.id];
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({ icon: quest.icon, title: quest.name, xp: quest.xp, message: 'クエスト完了！' });
    setParticles(quest.xp);
  }

  function handleCompleteCase(caseItem) {
    const xp        = 100;
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem('🎯', `${caseItem.full} クリア`, xp);
    const d  = applyXpGain(data, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({ icon: '🎯', title: `${caseItem.full} クリア！`, xp, message: '手順ガイド完了！' });
    setParticles(xp);
    navigator.vibrate?.([100, 50, 100]);
  }

  function handleFinanceComplete(problemId, correctCount, totalCount) {
    const problem = FINANCE_PROBLEMS.find(p => p.id === problemId);
    const prev = data.financeProgress?.[problemId] || { attempts: 0, bestCorrect: 0, completed: false };
    const newBest = Math.max(prev.bestCorrect, correctCount);
    const nowCompleted = newBest === totalCount;
    const alreadyCompleted = prev.completed;

    let d = {
      ...data,
      financeProgress: {
        ...data.financeProgress,
        [problemId]: { attempts: prev.attempts + 1, bestCorrect: newBest, completed: nowCompleted },
      },
    };

    let xpAwarded = 0;
    if (nowCompleted && !alreadyCompleted) {
      xpAwarded = problem.xp;
    } else if (!alreadyCompleted && correctCount > 0) {
      xpAwarded = correctCount * problem.partialXp;
    }

    if (xpAwarded > 0) {
      const hi = buildHistoryItem(problem.icon, `${problem.title} クリア`, xpAwarded);
      d = applyXpGain(d, xpAwarded, hi);
      commit(d);
      setReward({
        icon: problem.icon, title: problem.title, xp: xpAwarded,
        message: nowCompleted ? '全問正解！' : `${correctCount}/${totalCount} 正解`,
      });
      setParticles(xpAwarded);
    } else {
      commit(d);
    }
  }

  function handleDrillComplete({ mode, xp, missed }) {
    const label = mode === 'op' ? '間接法CFドリル（営業CF）' : '間接法CFドリル（3区分）';
    const prev = data.drillProgress?.[mode] || { attempts: 0, bestXp: 0 };
    let d = {
      ...data,
      drillProgress: {
        ...data.drillProgress,
        [mode]: { attempts: prev.attempts + 1, bestXp: Math.max(prev.bestXp, xp) },
      },
    };
    const prevLevel = getLevel(data.xp);
    const hi = buildHistoryItem('⚡', label, xp);
    d = applyXpGain(d, xp, hi);
    commit(d);
    const newLevel = getLevel(d.xp);
    if (newLevel.lv > prevLevel.lv) setLevelUp(newLevel);
    setReward({
      icon: '⚡', title: label, xp,
      message: missed.length === 0 ? '全項目ノーミス！' : `つまずき ${missed.length} 項目`,
    });
    setParticles(xp);
  }

  function handleCaseStudyComplete(problemId, correctCount, totalCount) {
    const problem = CASE_STUDY_PROBLEMS.find(p => p.id === problemId);
    const prev = data.caseProgress?.[problemId] || { attempts: 0, bestCorrect: 0, completed: false };
    const newBest = Math.max(prev.bestCorrect, correctCount);
    const nowCompleted = newBest === totalCount;
    const alreadyCompleted = prev.completed;

    let d = {
      ...data,
      caseProgress: {
        ...data.caseProgress,
        [problemId]: { attempts: prev.attempts + 1, bestCorrect: newBest, completed: nowCompleted },
      },
    };

    let xpAwarded = 0;
    if (nowCompleted && !alreadyCompleted) {
      xpAwarded = problem.xp;
    } else if (!alreadyCompleted && correctCount > 0) {
      xpAwarded = correctCount * problem.partialXp;
    }

    if (xpAwarded > 0) {
      const hi = buildHistoryItem(problem.icon, `${problem.title} クリア`, xpAwarded);
      d = applyXpGain(d, xpAwarded, hi);
      commit(d);
      setReward({
        icon: problem.icon, title: problem.title, xp: xpAwarded,
        message: nowCompleted ? '全問正解！' : `${correctCount}/${totalCount} 正解`,
      });
      setParticles(xpAwarded);
    } else {
      commit(d);
    }
  }

  function handleSaveNote(note, deleteId) {
    let notes = [...(data.notes || [])];
    if (deleteId) {
      notes = notes.filter(n => n.id !== deleteId);
    } else if (note) {
      notes = [...notes, note];
    }
    commit({ ...data, notes });
  }

  function handleUpdateProcedure(updates) {
    commit({ ...data, ...updates });
  }

  const remainingQuests = QUESTS.filter(q => !data.completedToday.includes(q.id)).length;

  return (
    <div style={{
      minHeight: '100vh', background: C.bg, color: C.text,
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
      maxWidth: 480, margin: '0 auto', position: 'relative',
    }}>
      {/* Header */}
      <div style={{
        background: '#0d1117', borderBottom: `1px solid ${C.border}`,
        padding: '14px 16px',
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        position: 'sticky', top: 0, zIndex: 100,
      }}>
        <div style={{ fontSize: 17, fontWeight: 700, color: C.accent }}>⚔️ 診断士クエスト</div>
        <div style={{ fontSize: 15, color: C.gold, fontWeight: 700 }}>{data.xp} XP</div>
      </div>

      {tab === 'quest' && (
        <QuestTab data={data} onCompleteQuest={handleCompleteQuest} onNavigate={setTab} />
      )}
      {tab === 'procedure' && (
        <ProcedureTab
          data={data}
          onCompleteCase={handleCompleteCase}
          onNavigate={setTab}
          onUpdateProcedure={handleUpdateProcedure}
        />
      )}
      {tab === 'reflection' && (
        <ReflectionTab data={data} onSaveNote={handleSaveNote} />
      )}
      {tab === 'history' && (
        <HistoryTab data={data} />
      )}
      {tab === 'finance' && (
        <FinanceTab data={data} onFinanceComplete={handleFinanceComplete} onCaseStudyComplete={handleCaseStudyComplete} onDrillComplete={handleDrillComplete} />
      )}

      <BottomNav active={tab} onChange={setTab} remainingCount={remainingQuests} />

      {reward   && <RewardPopup  reward={reward}  onClose={() => setReward(null)}   />}
      {particles && <XPParticles xp={particles}   onDone={() => setParticles(null)} />}
      {levelUp  && <LevelUpModal level={levelUp}  onClose={() => setLevelUp(null)}  />}
    </div>
  );
}
